// AAMC Question Bank Flashcards — Physics: original recall questions written from the concepts tested in the
// AAMC Physics Question Pack. No AAMC passages, questions or explanations are reproduced.
// Format: {s: tag, disc: scoring discipline, aamc: content category, q, choices: [4], ans: 0-3, exp, src}
const QB_AAMC_PHYS = [
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A radioisotope has a half-life of 5 days. How long does it take for only 1/16 of the original sample to remain?',choices:['15 days','20 days','80 days','16 days'],ans:1,exp:'1/16 = (1/2)⁴, so **4 half-lives** must pass: 4 × 5 days = 20 days. Multiplying 16 by the half-life (80 days) confuses the fraction remaining with the number of half-lives.',src:'aamc-phys-qpack:Q1'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'What fraction of a radioactive sample has decayed after 3 half-lives?',choices:['1/8','3/8','7/8','2/3'],ans:2,exp:'After 3 half-lives the fraction **remaining** is (1/2)³ = 1/8, so the fraction that has **decayed** is 1 − 1/8 = 7/8. Reporting 1/8 answers the remaining-fraction question instead.',src:'aamc-phys-qpack:Q1b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Two isotopes of the same element show nearly identical chemical behavior because they have the same:',choices:['number of neutrons','mass number','nuclear binding energy','number of protons'],ans:3,exp:'Isotopes share an **atomic number** (same protons, so the same number of electrons in the neutral atom), and chemistry is governed by electrons. They differ in neutron number and therefore in mass number.',src:'aamc-phys-qpack:Q2'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'An alpha particle is identical to which of the following?',choices:['A helium-4 nucleus','A hydrogen-2 nucleus','A helium-4 atom','A high-energy electron'],ans:0,exp:'An **alpha particle** is ⁴He²⁺: 2 protons and 2 neutrons with no electrons, so it carries a +2 charge. A neutral helium atom would also include two electrons; a high-energy electron is a beta-minus particle.',src:'aamc-phys-qpack:Q2b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Two parallel plates 2.0 cm apart are held at a potential difference of 12 V. What is the magnitude of the uniform electric field between them?',choices:['0.24 V/m','6.0 V/m','600 V/m','1200 V/m'],ans:2,exp:'For parallel plates **E = V/d** = 12 V ÷ 0.020 m = 600 V/m. Getting 6.0 V/m comes from forgetting to convert centimeters to meters; 0.24 V/m comes from multiplying instead of dividing.',src:'aamc-phys-qpack:Q3'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'The unit volt per meter (V/m), used for electric field strength, is equivalent to:',choices:['newtons per coulomb','joules per coulomb','coulombs per newton','newtons per joule'],ans:0,exp:'A volt is a joule per coulomb, so V/m = J/(C·m) = (N·m)/(C·m) = **N/C**, matching the definition E = F/q. Joules per coulomb is the unit of potential, not field.',src:'aamc-phys-qpack:Q3b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'What is the frequency of light with a wavelength of 500 nm in vacuum?',choices:['6.0×10¹⁴ Hz','1.5×10¹⁴ Hz','6.0×10¹⁵ Hz','1.7×10⁻¹⁵ Hz'],ans:0,exp:'**f = c/λ** = (3×10⁸ m/s) ÷ (5×10⁻⁷ m) = 6×10¹⁴ Hz. Dividing λ by c gives a tiny number with the wrong units (seconds), a common slip.',src:'aamc-phys-qpack:Q4'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'When light passes at an angle from air into glass, which property of the light stays the same?',choices:['Its speed','Its wavelength','Its direction','Its frequency'],ans:3,exp:'**Frequency** is set by the source and does not change at a boundary. Speed drops to c/n, so wavelength shrinks (λ = v/f), and an oblique ray bends toward the normal.',src:'aamc-phys-qpack:Q4b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Two waves of equal amplitude and frequency overlap. Complete destructive interference occurs when their phase difference is:',choices:['0°','90°','180°','360°'],ans:2,exp:'At a **180°** (half-wavelength) phase difference, crests meet troughs and equal amplitudes cancel. A difference of 0° or 360° puts crests on crests, giving fully constructive interference.',src:'aamc-phys-qpack:Q5'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Two in-phase sources of equal amplitude send waves to a point along paths that differ by 1.5 wavelengths. The interference at that point is:',choices:['fully constructive','fully destructive','partially destructive','partially constructive'],ans:1,exp:'A **half-integer** path difference (0.5λ, 1.5λ, 2.5λ…) produces a 180° phase difference, so the waves cancel completely. Whole-number path differences (λ, 2λ…) give fully constructive interference.',src:'aamc-phys-qpack:Q5b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'What is the difference in frequency between light of wavelength 300 nm and light of wavelength 600 nm?',choices:['5.0×10¹⁴ Hz','1.0×10¹⁵ Hz','1.5×10¹⁵ Hz','2.0×10¹⁴ Hz'],ans:0,exp:'Compute each frequency separately with **f = c/λ**: 1.0×10¹⁵ Hz (300 nm) − 5.0×10¹⁴ Hz (600 nm) = 5.0×10¹⁴ Hz. Dividing c by the wavelength difference (300 nm) wrongly gives 1.0×10¹⁵ Hz, because frequency is not linear in wavelength.',src:'aamc-phys-qpack:Q6'},
  {s:'Light & Optics',disc:'physics',aamc:'4E',q:'A photon has a frequency of 5.0×10¹⁴ Hz. Using h ≈ 6.6×10⁻³⁴ J·s, its energy is about:',choices:['3.3×10⁻¹⁹ J','1.3×10⁻⁴⁸ J','3.3×10⁻²⁰ J','7.6×10⁴⁷ J'],ans:0,exp:'**E = hf** = (6.6×10⁻³⁴)(5.0×10¹⁴) = 3.3×10⁻¹⁹ J, about 2 eV, typical of visible light. Higher frequency (shorter wavelength) means higher photon energy.',src:'aamc-phys-qpack:Q6b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'Compared with the fundamental of a vibrating string, its third harmonic has:',choices:['a period one-third as long','a period three times as long','the same period','a period one-ninth as long'],ans:0,exp:'The third harmonic has **3 times** the fundamental frequency, and since T = 1/f its period is one-third as long. Higher harmonics always mean higher frequency and shorter period.',src:'aamc-phys-qpack:Q7'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'A wave has a frequency of 250 Hz. What is its period?',choices:['0.025 s','0.04 s','250 s','0.004 s'],ans:3,exp:'**T = 1/f** = 1 ÷ 250 Hz = 0.004 s (4 ms). Period and frequency are reciprocals, so a larger frequency always means a shorter period.',src:'aamc-phys-qpack:Q7b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'For a string fixed at both ends, which points are nodes for every harmonic?',choices:['The two fixed ends','The midpoint only','The quarter points','No point is common'],ans:0,exp:'The **fixed ends** cannot move, so they are nodes (zero displacement) in every mode. The midpoint is an antinode for all odd harmonics, so it is not a universal node.',src:'aamc-phys-qpack:Q8'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'A string fixed at both ends vibrates in its third harmonic. How many nodes does the standing wave have, counting the ends?',choices:['2','3','6','4'],ans:3,exp:'The nth harmonic on a string has **n + 1 nodes** and n antinodes, so the third harmonic has 4 nodes (two at the ends, two in between) and 3 loops.',src:'aamc-phys-qpack:Q8b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'A string has a fundamental frequency of 150 Hz. What is the period of its second harmonic?',choices:['1/150 s','1/300 s','1/75 s','1/450 s'],ans:1,exp:'The nth harmonic has frequency **n × f₁**, so the second harmonic is 300 Hz and its period is 1/300 s (about 3.3 ms). A period of 1/150 s belongs to the fundamental.',src:'aamc-phys-qpack:Q9'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'For a string of length L fixed at both ends, the wavelength of the nth harmonic is:',choices:['L/n','4L/n','2L/n','nL/2'],ans:2,exp:'Each harmonic fits n half-wavelengths on the string, so L = nλ/2 and **λ = 2L/n**. The 4L/n form applies to a pipe closed at one end (odd n only).',src:'aamc-phys-qpack:Q9b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'Two instruments play the same note at the same loudness, yet they sound different. This difference in timbre arises mainly from differences in:',choices:['the relative strengths of harmonics','the fundamental frequency','the speed of sound in air','the overall wave amplitude'],ans:0,exp:'**Timbre** (tone quality) depends on which harmonics are present and how strong each is relative to the fundamental. Same note means the same fundamental, and same loudness means similar overall amplitude.',src:'aamc-phys-qpack:Q10'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'Which property of a sound wave primarily determines its perceived pitch?',choices:['Amplitude','Intensity level','Harmonic content','Frequency'],ans:3,exp:'**Pitch** tracks frequency: higher frequency is heard as a higher pitch. Amplitude and intensity level govern loudness, while harmonic content governs timbre.',src:'aamc-phys-qpack:Q10b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'As the harmonic number of a standing wave on a given string increases, which property necessarily increases?',choices:['Frequency','Amplitude','Wavelength','Wave speed'],ans:0,exp:'Each successive harmonic has a **higher frequency** (fₙ = nf₁) and a shorter wavelength. Amplitude depends on how the string is excited, not harmonic order, and wave speed is fixed by tension and mass per length.',src:'aamc-phys-qpack:Q11'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'A guitar string is plucked harder without changing its tension or length. Which quantity changes?',choices:['Frequency','Wave speed','Wavelength','Amplitude'],ans:3,exp:'Plucking harder puts more energy into the string, increasing **amplitude** (loudness). Wave speed depends on tension and linear density, and the standing-wave wavelengths are fixed by length, so frequency is unchanged.',src:'aamc-phys-qpack:Q11b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'A waveform is the sum of a 200 Hz fundamental and its second and third harmonics. The combined waveform repeats with a period of:',choices:['1.7 ms','2.5 ms','5.0 ms','3.3 ms'],ans:2,exp:'Every harmonic completes a whole number of cycles in one fundamental period, so the sum repeats every **1/f₁** = 1/200 s = 5.0 ms. The 1.7 ms and 2.5 ms values are the periods of the individual higher harmonics.',src:'aamc-phys-qpack:Q12'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'When two waves overlap in the same medium, the resulting displacement at each point equals:',choices:['the product of the individual displacements','the larger of the two displacements','the average of the two displacements','the sum of the individual displacements'],ans:3,exp:'By the **principle of superposition**, displacements add algebraically (with sign), which is what produces both constructive and destructive interference. The waves then pass through each other unchanged.',src:'aamc-phys-qpack:Q12b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Case 1: a radio source approaches a stationary receiver at 200 m/s. Case 2: the receiver approaches a stationary source at 200 m/s. How do the Doppler shifts compare?',choices:['equal in both cases','larger when the source moves','larger when the receiver moves','zero in both cases'],ans:0,exp:'For electromagnetic waves the Doppler shift depends only on the **relative velocity** between source and receiver, so equal closing speeds give equal shifts. (For sound, which has a medium, the two formulas differ slightly, but the difference is negligible at low speeds.)',src:'aamc-phys-qpack:Q13'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A car sounding its horn drives toward a stationary listener. Compared with the emitted sound, the listener hears:',choices:['a lower frequency','a higher frequency','the same frequency, louder','the same frequency, faster'],ans:1,exp:'When source and observer **approach**, wavefronts are compressed, so the observed frequency is higher (shorter wavelength). The speed of sound in still air is set by the medium and does not change.',src:'aamc-phys-qpack:Q13b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'For a light source receding at speed v much less than c, the fractional change in wavelength Δλ/λ is approximately:',choices:['c/v','(v/c)²','√(v/c)','v/c'],ans:3,exp:'At low speeds the Doppler shift is **Δλ/λ ≈ v/c**, so the wavelength shift grows linearly with recession speed. The same ratio applies to the fractional frequency shift, Δf/f.',src:'aamc-phys-qpack:Q14'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A spectral line emitted at 600 nm is observed at 606 nm in light from a distant galaxy. Approximately how fast is the galaxy receding?',choices:['3×10⁶ m/s','3×10⁴ m/s','3×10⁸ m/s','3×10⁵ m/s'],ans:0,exp:'Δλ/λ = 6/600 = 0.01, and **v ≈ c(Δλ/λ)** = 0.01 × 3×10⁸ m/s = 3×10⁶ m/s. The wavelength increased, so the galaxy is moving away (red shift).',src:'aamc-phys-qpack:Q14b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Light from a source moving directly away from an observer is received with:',choices:['shorter wavelength and higher frequency','longer wavelength and higher frequency','shorter wavelength and lower frequency','longer wavelength and lower frequency'],ans:3,exp:'A receding source stretches the wave: crests arrive farther apart, so wavelength is **longer** and frequency **lower** (red shift). Because v = fλ is fixed, wavelength and frequency must always shift in opposite directions.',src:'aamc-phys-qpack:Q15'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A shift of observed spectral lines toward longer wavelengths, caused by a receding source, is called:',choices:['blue shift','red shift','dispersion','diffraction'],ans:1,exp:'Longer wavelengths move toward the red end of the visible spectrum, so a receding source shows a **red shift**. An approaching source shows a blue shift; dispersion and diffraction are unrelated to source motion.',src:'aamc-phys-qpack:Q15b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A source moving at 30 m/s emits both sound and radio waves. Which shows the larger fractional Doppler shift?',choices:['Radio, because its wave speed is much higher','Both equally, since the source speed is the same','Sound, because its wave speed is much lower','Neither, since 30 m/s is too slow to shift'],ans:2,exp:'The fractional shift scales as **v_source/v_wave**. Sound travels about 340 m/s while radio travels 3×10⁸ m/s, so the same source speed produces a shift roughly a million times larger for sound.',src:'aamc-phys-qpack:Q16'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A siren emitting 1000 Hz approaches a stationary listener at 34 m/s. With the speed of sound 340 m/s, the listener hears about:',choices:['900 Hz','909 Hz','1000 Hz','1111 Hz'],ans:3,exp:'For an approaching source, **f′ = f·v/(v − vₛ)** = 1000 × 340/306 ≈ 1111 Hz. 909 Hz is what the listener would hear if the siren were moving away at the same speed.',src:'aamc-phys-qpack:Q16b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Two aircraft fly side by side at the same velocity while one transmits a radio signal to the other. The received frequency is:',choices:['equal to the transmitted frequency','higher than the transmitted frequency','lower than the transmitted frequency','dependent on the aircraft speed'],ans:0,exp:'The Doppler shift depends on **relative motion** between source and receiver. Moving together at the same velocity means zero relative velocity, so there is no shift no matter how fast both are flying.',src:'aamc-phys-qpack:Q17'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A buzzer moves at constant speed in a circle around a listener standing at the center. Compared with the emitted pitch, the listener hears:',choices:['a constant, unshifted frequency','a frequency alternating higher and lower','a constant, higher frequency','a constant, lower frequency'],ans:0,exp:'Only the velocity component **along the line** joining source and listener causes a Doppler shift. Circular motion about the listener is always perpendicular to that line, so the distance never changes and there is no shift.',src:'aamc-phys-qpack:Q17b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A spectral line measured in the lab at 500 nm appears at 495 nm in the light from a distant star. The star is:',choices:['moving away from Earth','at rest relative to Earth','moving perpendicular to the line of sight','moving toward Earth'],ans:3,exp:'A **shorter** observed wavelength is a blue shift, which means the source is approaching. A receding star would show a longer wavelength (red shift), and purely transverse motion gives no classical shift.',src:'aamc-phys-qpack:Q18'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'In Doppler ultrasound, blood flowing toward the transducer is identified because the reflected echo has:',choices:['a lower frequency','a lower speed','a higher speed','a higher frequency'],ans:3,exp:'Blood moving toward the probe compresses the reflected waves, so the echo returns at a **higher frequency**; flow away gives a lower frequency. The speed of sound in tissue is set by the tissue, not by the blood\'s motion.',src:'aamc-phys-qpack:Q18b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A block floats in water with 60% of its volume submerged on Earth. Floating in water on the Moon (g about one-sixth as large), the fraction submerged would be:',choices:['10%','60%','90%','100%'],ans:1,exp:'Fraction submerged = **ρ_object/ρ_fluid**. Both the weight and the buoyant force scale with g, so g cancels and the block floats at the same 60% depth on the Moon.',src:'aamc-phys-qpack:Q19'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A block floats in fresh water (1000 kg/m³) with 75% of its volume submerged. What is the block\'s density?',choices:['250 kg/m³','1333 kg/m³','750 kg/m³','1000 kg/m³'],ans:2,exp:'For a floating object, **ρ_object = (fraction submerged) × ρ_fluid** = 0.75 × 1000 = 750 kg/m³. 250 kg/m³ corresponds to the fraction above the surface, and anything denser than water would sink.',src:'aamc-phys-qpack:Q19b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'An open tank of water is emptied and refilled to the same depth with a liquid twice as dense. The absolute pressure at a given depth:',choices:['rises by less than 2×','doubles exactly','stays the same','rises by 4×'],ans:0,exp:'Absolute pressure is **P = P₀ + ρgh**. Only the ρgh term doubles; atmospheric pressure P₀ at the surface is unchanged, so the total rises by less than a factor of 2.',src:'aamc-phys-qpack:Q20'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'The gauge pressure at depth h in a fluid of density ρ that is open to the atmosphere (surface pressure P₀) equals:',choices:['ρgh','P₀ + ρgh','P₀ − ρgh','ρgh − P₀'],ans:0,exp:'**Gauge pressure** is pressure above atmospheric, so it is just ρgh. Absolute pressure adds the surface pressure: P₀ + ρgh.',src:'aamc-phys-qpack:Q20b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Light in air strikes a flat glass surface (n = 1.5) at 40° from the normal. Which describes the reflected and refracted rays?',choices:['Reflected at 40°; refracted at more than 40°','Reflected at less than 40°; refracted at 40°','Reflected at 40°; refracted at exactly 40°','Reflected at 40°; refracted at less than 40°'],ans:3,exp:'By the **law of reflection** the reflected angle equals 40°. Entering a higher-index medium, light bends **toward the normal** (n₁sinθ₁ = n₂sinθ₂), so the refraction angle is less than 40° (about 25°).',src:'aamc-phys-qpack:Q21'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Light passes from water (n = 1.33) into air with an angle of incidence of 30°. The angle of refraction is closest to:',choices:['22°','30°','90°','42°'],ans:3,exp:'**Snell\'s law**: sinθ₂ = (1.33)(sin30°)/1.00 = 0.665, so θ₂ ≈ 42°. Going into a lower-index medium, light bends away from the normal; 22° results from inverting the index ratio.',src:'aamc-phys-qpack:Q21b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A sample\'s activity drops from 800 to 100 counts per minute in 45 minutes. What is its half-life?',choices:['5.6 min','15 min','22.5 min','45 min'],ans:1,exp:'800 → 400 → 200 → 100 is a factor of 8 = 2³, so **3 half-lives** elapsed: 45 min ÷ 3 = 15 min. Dividing by 8 (5.6 min) confuses the decay factor with the number of half-lives.',src:'aamc-phys-qpack:Q22'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'The activity (decays per second) of a radioactive sample is directly proportional to:',choices:['the age of the sample','the temperature of the sample','the number of undecayed nuclei','the half-life of the isotope'],ans:2,exp:'Activity is **A = λN**, where N is the number of undecayed nuclei and λ = ln2/t½. Activity is therefore inversely related to half-life, and nuclear decay is independent of temperature.',src:'aamc-phys-qpack:Q22b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'5E',q:'Heat is added steadily to an ice-water mixture at 0 °C and 1 atm. Until all the ice has melted, the temperature of the mixture:',choices:['stays at 0 °C','rises steadily','drops slightly','rises, then levels off'],ans:0,exp:'During a **phase change**, added heat supplies the latent heat of fusion to break the solid\'s structure rather than raising kinetic energy, so temperature stays constant. Only after all the ice melts does the temperature rise again.',src:'aamc-phys-qpack:Q23'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'5E',q:'How much heat is needed to melt 2.0 kg of ice already at 0 °C? (latent heat of fusion = 334 kJ/kg)',choices:['167 kJ','334 kJ','1336 kJ','668 kJ'],ans:3,exp:'Melting uses **Q = mL_f** = 2.0 kg × 334 kJ/kg = 668 kJ, with no temperature change. Q = mcΔT does not apply because ΔT is zero during the phase change.',src:'aamc-phys-qpack:Q23b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Two parallel plates stay connected to a battery of fixed voltage while their separation is doubled. The electric field between the plates:',choices:['doubles','is halved','quadruples','is unchanged'],ans:1,exp:'With V held fixed, **E = V/d**, so doubling d halves the field. The battery keeps the potential difference constant while the plates move apart.',src:'aamc-phys-qpack:Q24'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A charged parallel-plate capacitor is disconnected from its battery, then its plate separation is doubled. The electric field between the plates:',choices:['doubles','is halved','is unchanged','quadruples'],ans:2,exp:'Isolated plates keep their charge, and the field depends only on charge density: **E = σ/ε₀** = Q/(ε₀A). The voltage doubles instead (V = Ed), which is the key contrast with a battery-connected capacitor.',src:'aamc-phys-qpack:Q24b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'An electron starting nearly at rest is accelerated through a potential difference of 200 V. How much kinetic energy does it gain?',choices:['100 eV','400 eV','0.5 eV','200 eV'],ans:3,exp:'The work done by the field is **ΔKE = |q|ΔV** = e × 200 V = 200 eV (about 3.2×10⁻¹⁷ J). The ½ in ½mv² does not enter; the energy is simply charge times voltage.',src:'aamc-phys-qpack:Q25'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'One electron-volt (1 eV) is equal to:',choices:['1.6×10⁻¹⁹ J','6.2×10¹⁸ J','1.6×10⁻¹⁹ C','9.1×10⁻³¹ J'],ans:0,exp:'An **electron-volt** is the energy one elementary charge gains across 1 V: (1.6×10⁻¹⁹ C)(1 V) = 1.6×10⁻¹⁹ J. 1.6×10⁻¹⁹ C is the elementary charge itself, a unit of charge, not energy.',src:'aamc-phys-qpack:Q25b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Light above the threshold frequency strikes a metal. Doubling the light\'s intensity at the same frequency:',choices:['doubles the number of electrons ejected per second','doubles the maximum kinetic energy of electrons','raises the threshold frequency of the metal','has no effect on the photocurrent'],ans:0,exp:'Intensity sets the **number of photons** per second, so more electrons are ejected and the current rises. Each electron still absorbs one photon of the same energy, so KEmax = hf − φ is unchanged.',src:'aamc-phys-qpack:Q26'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'In a photoelectric cell illuminated above its threshold frequency, the photocurrent is proportional to:',choices:['the frequency of the incident light','the work function of the metal','the wavelength of the incident light','the number of incident photons per second'],ans:3,exp:'Each absorbed photon can free at most one electron, so the current tracks the **photon arrival rate** (intensity). Frequency controls the electrons\' maximum kinetic energy, not how many are ejected.',src:'aamc-phys-qpack:Q26b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'An electron is released from rest in the uniform field between two oppositely charged parallel plates. It will:',choices:['accelerate uniformly toward the negative plate','move at constant velocity toward the positive plate','remain at rest between the plates','accelerate uniformly toward the positive plate'],ans:3,exp:'A uniform field exerts a **constant force** F = qE, so the electron undergoes constant acceleration. Being negative, it is pushed opposite the field lines, toward the positive plate (the anode).',src:'aamc-phys-qpack:Q27'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'The direction of an electric field at a point is defined as the direction of the force on:',choices:['a positive test charge','a negative test charge','an electron at rest','a moving magnetic dipole'],ans:0,exp:'By convention, **E** points in the direction of the force on a small positive test charge, so field lines run from positive to negative charges. Negative charges, including electrons, feel a force opposite to E.',src:'aamc-phys-qpack:Q27b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'In a vacuum photodiode wired to a battery, light on the cathode causes current to flow in the external circuit because:',choices:['photons carry charge across the gap to the anode','light raises the battery\'s emf above its rating','ejected electrons cross the gap and complete the circuit','the vacuum becomes ionized and conducts like a wire'],ans:2,exp:'Photoelectrons leave the cathode and are collected at the anode, **closing the circuit** so charge can flow; the battery maintains the voltage. Photons are neutral and carry no charge.',src:'aamc-phys-qpack:Q28'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Conventional current in a metal wire flows:',choices:['in the same direction as electron flow','opposite to the direction of electron flow','from the negative terminal through the load','perpendicular to the direction of electron flow'],ans:1,exp:'**Conventional current** is defined as the flow of positive charge, so it points opposite to the motion of electrons, from the positive terminal through the external circuit to the negative terminal.',src:'aamc-phys-qpack:Q28b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A metal has a work function of 2.0 eV. Photons of energy 5.0 eV strike it. What is the maximum kinetic energy of the ejected electrons?',choices:['3.0 eV','2.0 eV','5.0 eV','7.0 eV'],ans:0,exp:'Einstein\'s photoelectric equation: **KEmax = hf − φ** = 5.0 − 2.0 = 3.0 eV. Adding the work function (7.0 eV) is a sign error; energy is spent freeing the electron.',src:'aamc-phys-qpack:Q29'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Light of steadily increasing frequency shines on a metal of work function φ. Electrons are first ejected when the frequency reaches:',choices:['h/φ','hφ','φ/c','φ/h'],ans:3,exp:'Ejection begins when the photon energy equals the work function: hf₀ = φ, so the **threshold frequency** is f₀ = φ/h. Below f₀ no electrons are ejected, however intense the light.',src:'aamc-phys-qpack:Q29b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A charged particle moves through a uniform electric field. If its speed doubles, the electric force on it:',choices:['doubles','is halved','quadruples','is unchanged'],ans:3,exp:'The electric force **F = qE** depends only on charge and field, not on velocity. Contrast the magnetic force qvB sinθ, which does depend on speed.',src:'aamc-phys-qpack:Q30'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A charged particle moves perpendicular to a uniform magnetic field. If its speed is increased by a factor of 2, the magnetic force on it:',choices:['doubles','is halved','is unchanged','quadruples'],ans:0,exp:'The magnetic force is **F = qvB sinθ**, which is proportional to speed, so doubling v doubles F. A stationary charge feels no magnetic force at all.',src:'aamc-phys-qpack:Q30b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Which change increases the capacitance of a parallel-plate capacitor?',choices:['Increasing the plate separation','Increasing the plate area','Increasing the applied voltage','Increasing the series resistance'],ans:1,exp:'**C = ε₀A/d** (times κ with a dielectric) depends only on geometry and material, so larger plate area raises C. Greater separation lowers C, and voltage or resistance change charge and timing, not capacitance.',src:'aamc-phys-qpack:Q31'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A dielectric with κ = 3 is inserted to fill a capacitor that remains connected to its battery. The stored charge:',choices:['triples','is unchanged','drops to one-third','increases ninefold'],ans:0,exp:'The dielectric multiplies capacitance by **κ**, and with V held fixed by the battery, Q = CV triples. If the capacitor were isolated instead, Q would stay fixed and the voltage would drop to one-third.',src:'aamc-phys-qpack:Q31b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A proton (m ≈ 1.7×10⁻²⁷ kg, q = 1.6×10⁻¹⁹ C) is in a uniform 1.0×10³ N/C electric field. What is its acceleration?',choices:['1.6×10⁻¹⁶ m/s²','1.1×10⁻¹¹ m/s²','9.4×10¹⁰ m/s²','9.4×10⁷ m/s²'],ans:2,exp:'Set **qE = ma**: a = (1.6×10⁻¹⁹ × 1.0×10³)/(1.7×10⁻²⁷) ≈ 9.4×10¹⁰ m/s². 1.6×10⁻¹⁶ is the force in newtons, not the acceleration.',src:'aamc-phys-qpack:Q32'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'An electron and a proton are placed in the same uniform electric field. They experience:',choices:['equal accelerations, unequal force magnitudes','equal force magnitudes, unequal accelerations','equal force magnitudes and equal accelerations','unequal force magnitudes and unequal accelerations'],ans:1,exp:'Their charges have equal magnitude, so **|F| = eE** is the same for both. Since a = F/m and the electron is about 1836 times lighter, its acceleration is far larger (and opposite in direction).',src:'aamc-phys-qpack:Q32b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Two identical 6 μF capacitors are connected in series. What is the equivalent capacitance?',choices:['3 μF','6 μF','12 μF','36 μF'],ans:0,exp:'In series, **1/C_eq = 1/C₁ + 1/C₂** = 1/6 + 1/6, so C_eq = 3 μF. Capacitors combine opposite to resistors: series capacitors act like a larger plate separation.',src:'aamc-phys-qpack:Q33'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Two identical 6 μF capacitors are connected in parallel. What is the equivalent capacitance?',choices:['3 μF','6 μF','12 μF','36 μF'],ans:2,exp:'In parallel, capacitances simply **add**: 6 + 6 = 12 μF, like increasing the total plate area. Resistors follow the opposite rule (series resistances add).',src:'aamc-phys-qpack:Q33b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A negatively charged oil drop sits between horizontal plates; the top plate is positive and the bottom plate negative. The electric force on the drop points:',choices:['downward, toward the negative plate','upward, toward the negative plate','horizontally, parallel to the plates','upward, toward the positive plate'],ans:3,exp:'The field points from the positive (top) plate to the negative (bottom) plate, i.e., downward, and a **negative charge** feels force opposite to E, so it is pushed upward toward the positive plate. This is the setup of Millikan\'s oil-drop experiment.',src:'aamc-phys-qpack:Q34'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'How much energy is stored in a 10 μF capacitor charged to 100 V?',choices:['0.1 J','0.05 J','1 mJ','500 J'],ans:1,exp:'**U = ½CV²** = ½(10×10⁻⁶ F)(100 V)² = 0.05 J. Forgetting the ½ gives 0.1 J; 1 mC (not 1 mJ) is the stored charge Q = CV.',src:'aamc-phys-qpack:Q34b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'In a plasma oscillation, the positive ions stay nearly stationary while the electrons oscillate mainly because the ions have:',choices:['much smaller charge','opposite charge sign','much greater mass','much weaker fields'],ans:2,exp:'Ions and electrons feel comparable electric forces, but ions are thousands of times **more massive**, so their acceleration (a = F/m) is tiny. Inertia keeps them effectively fixed on the timescale of the electron motion.',src:'aamc-phys-qpack:Q35'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'An electron and a proton start from rest in the same uniform electric field. After the same short time, the ratio of the electron\'s speed to the proton\'s speed is about:',choices:['1','43','1836','1/1836'],ans:2,exp:'Equal force magnitudes give accelerations inversely proportional to mass, and v = at, so **v_e/v_p = m_p/m_e** ≈ 1836. The ratio 43 (≈√1836) would apply if they had equal kinetic energies instead.',src:'aamc-phys-qpack:Q35b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'For a mass on a spring undergoing simple harmonic motion, the potential energy is maximum:',choices:['at the equilibrium position','at maximum displacement','halfway to maximum displacement','when the speed is maximum'],ans:1,exp:'Spring potential energy is **U = ½kx²**, which peaks at the turning points (x = ±A), where the mass is momentarily at rest. Kinetic energy and speed are maximum at equilibrium, where U = 0.',src:'aamc-phys-qpack:Q36'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'The period of a mass-spring oscillator is T = 2π√(m/k). Quadrupling the mass:',choices:['doubles the period','quadruples the period','halves the period','leaves the period unchanged'],ans:0,exp:'T ∝ **√m**, so 4× the mass gives √4 = 2× the period. The period does not depend on amplitude, and for a pendulum it depends on length and g rather than mass.',src:'aamc-phys-qpack:Q36b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'The plasma frequency is given by f ≈ 9√n (f in Hz, n in electrons/m³). What is f when n = 4×10¹⁶ m⁻³?',choices:['3.6×10¹⁷ Hz','1.8×10⁸ Hz','9.0×10⁸ Hz','1.8×10⁹ Hz'],ans:3,exp:'√(4×10¹⁶) = **2×10⁸** (take the square root of the coefficient and halve the exponent), so f ≈ 9 × 2×10⁸ = 1.8×10⁹ Hz. Skipping the square root gives 3.6×10¹⁷ Hz.',src:'aamc-phys-qpack:Q37'},
  {s:'Waves & Sound',disc:'physics',aamc:'4A',q:'If a quantity is proportional to √n, what happens to it when n increases by a factor of 4?',choices:['It quadruples','It doubles','It increases 16-fold','It is unchanged'],ans:1,exp:'For a **square-root** dependence, the factor is √4 = 2, so the quantity doubles. Square-root scaling appears often on the MCAT, e.g., v = √(2gh) and wave speed v = √(T/μ).',src:'aamc-phys-qpack:Q37b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A wave travels at 2×10⁸ m/s with a frequency of 4×10⁹ Hz. What is its wavelength?',choices:['0.5 cm','5 cm','20 cm','50 cm'],ans:1,exp:'**λ = v/f** = (2×10⁸ m/s) ÷ (4×10⁹ Hz) = 0.05 m = 5 cm. Keep track of powers of ten: 10⁸/10⁹ = 10⁻¹, and 2/4 = 0.5.',src:'aamc-phys-qpack:Q38'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A sound wave passes from air into water, where sound travels faster. Its wavelength:',choices:['decreases, frequency unchanged','is unchanged, frequency increases','increases, frequency unchanged','increases, frequency increases'],ans:2,exp:'**Frequency** is fixed by the source and does not change at a boundary, so with v = fλ a higher speed means a longer wavelength. Sound travels about 1500 m/s in water versus 340 m/s in air.',src:'aamc-phys-qpack:Q38b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'As a pendulum swings from its highest point toward its lowest point (no friction):',choices:['kinetic energy converts to potential energy','potential energy converts to kinetic energy','total mechanical energy increases','both kinetic and potential energy increase'],ans:1,exp:'Moving from a turning point toward equilibrium, **potential energy is converted to kinetic energy** while total mechanical energy stays constant. Speed is greatest at the bottom of the swing.',src:'aamc-phys-qpack:Q39'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 0.5 kg mass on a spring (k = 200 N/m) oscillates with an amplitude of 0.10 m. What is its maximum speed?',choices:['1 m/s','4 m/s','20 m/s','2 m/s'],ans:3,exp:'Energy conservation: **½kA² = ½mv²max**, so ½(200)(0.10)² = 1 J = ½(0.5)v², giving v² = 4 and v = 2 m/s. All the spring\'s potential energy becomes kinetic energy at equilibrium.',src:'aamc-phys-qpack:Q39b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A train sounds its whistle while moving away from a platform. Compared with the emitted frequency, a listener on the platform hears:',choices:['a lower frequency','a higher frequency','the same frequency','a steadily rising frequency'],ans:0,exp:'A **receding** source stretches the wavefronts, increasing wavelength and lowering the observed frequency. At constant speed the shift is constant, so the pitch does not keep changing.',src:'aamc-phys-qpack:Q40'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A listener runs at 34 m/s toward a stationary 500 Hz source. With the speed of sound 340 m/s, the listener hears:',choices:['450 Hz','500 Hz','550 Hz','556 Hz'],ans:2,exp:'For a moving observer, **f′ = f(v + v_o)/v** = 500 × 374/340 = 550 Hz. 556 Hz is the result for a source moving toward a stationary listener at the same speed; the two cases differ slightly for sound.',src:'aamc-phys-qpack:Q40b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A pipe closed at one end has two consecutive resonant frequencies of 150 Hz and 250 Hz. What is its fundamental frequency?',choices:['50 Hz','100 Hz','150 Hz','25 Hz'],ans:0,exp:'A closed pipe supports only **odd harmonics** (f₁, 3f₁, 5f₁…), so consecutive resonances differ by 2f₁: 100 Hz = 2f₁ gives f₁ = 50 Hz (150 = 3 × 50, 250 = 5 × 50). Taking the difference itself as f₁ is the open-pipe rule.',src:'aamc-phys-qpack:Q41'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A pipe open at both ends is 0.85 m long. With the speed of sound 340 m/s, what is its fundamental frequency?',choices:['100 Hz','200 Hz','400 Hz','800 Hz'],ans:1,exp:'An open pipe has antinodes at both ends, so **L = λ/2** for the fundamental: λ = 1.7 m and f = 340/1.7 = 200 Hz. Using the closed-pipe relation L = λ/4 would give 100 Hz.',src:'aamc-phys-qpack:Q41b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A sound has an intensity level of 80 dB. What is its intensity? (I₀ = 10⁻¹² W/m²)',choices:['10⁻⁸ W/m²','10⁸ W/m²','10⁻⁴ W/m²','10⁻¹⁰ W/m²'],ans:2,exp:'**β = 10 log(I/I₀)**: 80 = 10 log(I/10⁻¹²), so I/I₀ = 10⁸ and I = 10⁸ × 10⁻¹² = 10⁻⁴ W/m². Each 10 dB step multiplies intensity by 10.',src:'aamc-phys-qpack:Q42'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A sound has an intensity of 10⁻⁶ W/m². What is its intensity level? (I₀ = 10⁻¹² W/m²)',choices:['6 dB','60 dB','−60 dB','120 dB'],ans:1,exp:'I/I₀ = 10⁻⁶/10⁻¹² = 10⁶, and **β = 10 log(10⁶)** = 60 dB, roughly normal conversation. Forgetting the factor of 10 gives 6 dB.',src:'aamc-phys-qpack:Q42b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A crane lifts a 200 kg load 5 m at constant speed, then lowers it 5 m at constant speed (g = 9.8 m/s²). The work done by the cable in each case is:',choices:['+9.8 kJ, then zero','zero in both cases','+9.8 kJ, then +9.8 kJ','+9.8 kJ, then −9.8 kJ'],ans:3,exp:'At constant speed the cable tension equals **mg**, so the work has magnitude mgh = 200 × 9.8 × 5 = 9.8 kJ both ways. Tension acts along the motion when lifting (positive work) and opposite it when lowering (negative work).',src:'aamc-phys-qpack:Q43'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 2 kg book is lifted 1.5 m at constant speed. How much work does gravity do on it? (g = 10 m/s²)',choices:['−30 J','+30 J','0 J','−3 J'],ans:0,exp:'Gravity points down while the displacement is up, so **W = −mgh** = −(2)(10)(1.5) = −30 J. The lifting force does +30 J, so the net work is zero, consistent with constant speed.',src:'aamc-phys-qpack:Q43b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A small negative charge is released near a fixed positive point charge. As it moves, its acceleration:',choices:['points away from the positive charge and decreases','points toward the positive charge and increases','points toward the positive charge and stays constant','points away from the positive charge and increases'],ans:1,exp:'Opposite charges attract, so the charge accelerates toward the positive charge. **Coulomb\'s law** (F = kq₁q₂/r²) means the force, and hence the acceleration, grows as the separation shrinks.',src:'aamc-phys-qpack:Q44'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'The distance between two point charges is halved. The electrostatic force between them:',choices:['is halved','doubles','quadruples','drops to one-fourth'],ans:2,exp:'Coulomb force is an **inverse-square** law, F ∝ 1/r², so halving r multiplies F by 2² = 4. Dropping to one-fourth would result from doubling the distance.',src:'aamc-phys-qpack:Q44b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A constant 25 N force pushes a crate 0.40 m in the direction of the force. How much work does the force do?',choices:['0.016 J','10 J','25 J','62.5 J'],ans:1,exp:'**W = Fd cosθ** with θ = 0: 25 N × 0.40 m = 10 J. Dividing distance by force (0.016 J) or force by distance (62.5 J) gives the wrong dimension.',src:'aamc-phys-qpack:Q45'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 50 N force acts at 60° to a box\'s displacement as the box moves 4 m. How much work does the force do?',choices:['200 J','173 J','50 J','100 J'],ans:3,exp:'Only the component along the displacement does work: **W = Fd cosθ** = 50 × 4 × cos60° = 50 × 4 × 0.5 = 100 J. Using sin60° instead gives 173 J.',src:'aamc-phys-qpack:Q45b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A ball is launched straight up at 20 m/s with no air resistance (g = 10 m/s²). How high does it rise?',choices:['2 m','10 m','20 m','40 m'],ans:2,exp:'Energy conservation: ½mv² = mgh, so **h = v²/2g** = 400/20 = 20 m. Mass cancels, so a heavier ball launched at the same speed reaches the same height.',src:'aamc-phys-qpack:Q46'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'If the launch speed of a vertically thrown ball is doubled (no air resistance), its maximum height:',choices:['doubles','quadruples','increases by a factor of √2','stays the same'],ans:1,exp:'Because **h = v²/2g**, height scales with the square of launch speed, so 2× the speed gives 4× the height. Time in the air (2v/g) only doubles.',src:'aamc-phys-qpack:Q46b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A speaker emitting 680 Hz is momentarily at rest at the top of its vertical flight. With the speed of sound 340 m/s, what wavelength reaches a listener below at that instant?',choices:['2.0 m','1.0 m','0.5 m','0.25 m'],ans:2,exp:'At the peak the source velocity is zero, so there is **no Doppler shift** and λ = v/f = 340/680 = 0.5 m. Dividing f by v instead gives 2.0 m.',src:'aamc-phys-qpack:Q47'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'The speed of sound in a given medium is determined by:',choices:['the source frequency','the medium\'s properties','the source amplitude','the source\'s speed'],ans:1,exp:'Wave speed depends on the **medium** (its stiffness/bulk modulus and density, and for gases its temperature). Changing the source frequency changes the wavelength, not the speed.',src:'aamc-phys-qpack:Q47b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A buzzer is thrown straight up and later caught at its launch height. Compared with the emitted pitch, a listener at the launch point hears a pitch that is:',choices:['lower rising, equal at the top, higher falling','higher rising, equal at the top, lower falling','lower throughout the entire flight','higher throughout the entire flight'],ans:0,exp:'Rising, the buzzer moves **away** (lower pitch); at the top it is momentarily at rest (no shift); falling, it moves **toward** the listener (higher pitch).',src:'aamc-phys-qpack:Q48'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'For a buzzer thrown straight up and caught at launch height, when is the magnitude of its Doppler shift greatest (no air resistance)?',choices:['At the top of the flight','Halfway up, while rising','Just after launch and just before catch','It is constant throughout'],ans:2,exp:'The shift magnitude tracks the **source speed**, which is greatest at launch and catch (equal speeds, by symmetry) and zero at the top.',src:'aamc-phys-qpack:Q48b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A convex mirror has a radius of curvature of 40 cm. What is the magnitude of its focal length?',choices:['10 cm','20 cm','40 cm','80 cm'],ans:1,exp:'For a spherical mirror **f = R/2** = 20 cm; by convention it is negative (−20 cm) for a convex mirror, which only forms virtual, upright, reduced images.',src:'aamc-phys-qpack:Q49'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A curved mirror is moved from air into water. Its focal length:',choices:['decreases by a factor of n','increases by a factor of n','is unchanged','reverses sign'],ans:2,exp:'A mirror works by **reflection**, and the angle of reflection does not depend on the surrounding medium, so f = R/2 stays the same. A lens, by contrast, depends on refraction, and its focal length does change in water.',src:'aamc-phys-qpack:Q49b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Which equation is Snell\'s law for refraction at an interface?',choices:['n₁cosθ₁ = n₂cosθ₂','n₁/sinθ₁ = n₂/sinθ₂','n₁θ₂ = n₂θ₁','n₁sinθ₁ = n₂sinθ₂'],ans:3,exp:'**Snell\'s law** is n₁sinθ₁ = n₂sinθ₂, with angles measured from the normal. It implies that light bends toward the normal when entering a higher-index medium.',src:'aamc-phys-qpack:Q50'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'What is the critical angle for total internal reflection when light travels from glass (n = 1.5) toward air?',choices:['48°','42°','34°','90°'],ans:1,exp:'Set θ₂ = 90° in Snell\'s law: **sinθc = n₂/n₁** = 1/1.5 ≈ 0.667, so θc ≈ 42°. Total internal reflection only occurs going from higher to lower index; 48° is the complement of the true angle.',src:'aamc-phys-qpack:Q50b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Parallel light rays pass through a diverging lens. After the lens, the rays:',choices:['converge to a real focal point beyond the lens','spread apart as if from a virtual focal point','emerge parallel to their original direction','converge and then cross the optical axis'],ans:1,exp:'A **diverging** (concave) lens spreads parallel rays so they appear to come from a focal point on the incoming side; that focus is virtual and f is negative. Converging lenses (f > 0) bring parallel rays to a real focus.',src:'aamc-phys-qpack:Q51'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'An object is 30 cm in front of a converging lens with focal length 10 cm. Where is the image?',choices:['−15 cm','7.5 cm','20 cm','15 cm'],ans:3,exp:'**1/f = 1/o + 1/i**: 1/i = 1/10 − 1/30 = 2/30, so i = +15 cm, a real, inverted image on the far side of the lens. Adding the reciprocals instead of subtracting gives 7.5 cm.',src:'aamc-phys-qpack:Q51b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'In a simple model, light travels more slowly in glass than in vacuum because:',choices:['its frequency decreases as it enters the glass','its photons lose energy to the glass as heat','it is absorbed and re-emitted by electrons in the glass','its wavelength increases inside the glass'],ans:2,exp:'In the standard MCAT picture, light interacts with the material\'s electrons, which **absorb and re-emit** it, delaying the wave so v = c/n. Frequency is unchanged at the boundary, and wavelength actually decreases inside the glass.',src:'aamc-phys-qpack:Q52'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'What is the speed of light in a material with refractive index n = 1.5?',choices:['2.0×10⁸ m/s','4.5×10⁸ m/s','1.5×10⁸ m/s','3.0×10⁸ m/s'],ans:0,exp:'**v = c/n** = (3.0×10⁸ m/s)/1.5 = 2.0×10⁸ m/s. Multiplying by n would give a speed faster than c, which is impossible for a material medium.',src:'aamc-phys-qpack:Q52b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A capacitor charging from a battery through a resistor stops gaining charge when:',choices:['its charge equals the battery\'s charge','the resistor has absorbed all the energy','its plates run out of free electrons','its voltage equals the battery voltage'],ans:3,exp:'Charge on the plates **repels** further incoming charge; once the capacitor voltage Q/C equals the battery emf, no potential difference remains across the resistor and current stops. The final charge is Q = CV.',src:'aamc-phys-qpack:Q53'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A 4 μF capacitor is fully charged by a 9 V battery. How much charge does it hold?',choices:['2.25 μC','36 μC','0.44 μC','162 μC'],ans:1,exp:'**Q = CV** = 4 μF × 9 V = 36 μC. Dividing C by V or V by C gives the other values; 162 μJ would be the stored energy ½CV², not a charge.',src:'aamc-phys-qpack:Q53b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A capacitor discharges through a variable resistor. To keep the current constant as the capacitor\'s voltage falls, the resistance must:',choices:['decrease steadily','increase steadily','stay constant','oscillate periodically'],ans:0,exp:'Ohm\'s law gives **I = V/R**; as V drops, R must drop in proportion for I to stay fixed. With a fixed resistor, the current would instead decay along with the voltage.',src:'aamc-phys-qpack:Q54'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A charged capacitor discharges through a fixed resistor. Over time, the current:',choices:['decreases linearly','stays constant','decreases exponentially','increases exponentially'],ans:2,exp:'As charge leaves, the voltage falls, so the current V/R falls too, giving **exponential decay** I = I₀e^(−t/RC). After one time constant (τ = RC) about 37% of the initial current remains.',src:'aamc-phys-qpack:Q54b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Which circuit element dissipates electrical energy as heat rather than storing it?',choices:['Capacitor','Resistor','Battery','Inductor'],ans:1,exp:'A **resistor** converts electrical energy to thermal energy at the rate P = I²R. Capacitors store energy in an electric field (½CV²), inductors in a magnetic field, and batteries in chemical form.',src:'aamc-phys-qpack:Q55'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A current of 3 A flows through a 5 Ω resistor. How much power does it dissipate?',choices:['15 W','75 W','45 W','1.7 W'],ans:2,exp:'**P = I²R** = (3 A)² × 5 Ω = 45 W. Multiplying I by R gives the voltage (15 V), not the power.',src:'aamc-phys-qpack:Q55b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'At the start of a discharge, 9 V is across a resistor carrying 3 mA. What is the resistance?',choices:['0.027 Ω','3 Ω','3000 Ω','3.3×10⁻⁴ Ω'],ans:2,exp:'**R = V/I** = 9 V ÷ 0.003 A = 3000 Ω. Forgetting to convert milliamps to amps gives 3 Ω.',src:'aamc-phys-qpack:Q56'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A constant 2 mA current drains a capacitor for 50 s. How much charge flows?',choices:['100 C','4×10⁻⁵ C','25 C','0.1 C'],ans:3,exp:'For a constant current, **Q = It** = 0.002 A × 50 s = 0.1 C. Using 2 A instead of 2 mA gives 100 C.',src:'aamc-phys-qpack:Q56b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A sled is pulled at constant velocity by a rope with tension T at angle θ above the horizontal. What is the magnitude of the kinetic friction force?',choices:['T sinθ','T cosθ','T','T tanθ'],ans:1,exp:'Constant velocity means **zero net force**, so friction must balance the horizontal component of the pull: f = T cosθ. The vertical component T sinθ instead reduces the normal force.',src:'aamc-phys-qpack:Q57'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A sled of mass m on level ground is pulled by a rope with tension T at angle θ above the horizontal. What is the normal force on the sled?',choices:['mg','mg + T sinθ','mg − T sinθ','mg − T cosθ'],ans:2,exp:'Vertical forces balance: N + T sinθ = mg, so **N = mg − T sinθ**. The upward pull lightens the load on the ground, which also lowers the friction force μN.',src:'aamc-phys-qpack:Q57b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'Mercury is about 13.6 times as dense as water. How does the gauge pressure 10 cm below a mercury surface compare with that 40 cm below a water surface?',choices:['13.6 times as great','0.29 times as great','3.4 times as great','54 times as great'],ans:2,exp:'Gauge pressure is **ρgh**, so the ratio is (13.6 × 10 cm)/(1 × 40 cm) = 3.4. Both the density and the depth must enter the comparison.',src:'aamc-phys-qpack:Q58'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A diver is 20 m below the surface of fresh water (ρ = 1000 kg/m³, g = 10 m/s², P₀ = 1.0×10⁵ Pa). What is the absolute pressure on the diver?',choices:['2.0×10⁵ Pa','3.0×10⁵ Pa','1.2×10⁵ Pa','2.1×10⁶ Pa'],ans:1,exp:'**P = P₀ + ρgh** = 1.0×10⁵ + (1000)(10)(20) = 3.0×10⁵ Pa, about 3 atm. 2.0×10⁵ Pa is the gauge pressure alone; roughly every 10 m of water adds 1 atm.',src:'aamc-phys-qpack:Q58b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Raising a sound\'s intensity level by 30 dB multiplies its intensity by:',choices:['30','100','1000','3000'],ans:2,exp:'Each **+10 dB** multiplies intensity by 10, so +30 dB gives 10 × 10 × 10 = 1000. Likewise +20 dB is a factor of 100, not 20.',src:'aamc-phys-qpack:Q59'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'The sound intensity 2 m from a point source is I. Ignoring absorption, what is the intensity 6 m from the source?',choices:['I/3','I/6','I/36','I/9'],ans:3,exp:'Power spreads over a sphere of area 4πr², so **I ∝ 1/r²**: tripling the distance divides intensity by 3² = 9. Dividing by 3 treats intensity as falling off linearly.',src:'aamc-phys-qpack:Q59b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'To calculate a sound source\'s speed from its Doppler shift, which quantity is NOT needed?',choices:['the speed of sound in the medium','the distance between source and observer','the emitted frequency of the source','the frequency heard by the observer'],ans:1,exp:'The **Doppler equation** relates the emitted and observed frequencies to the source and wave speeds; distance never appears. Distance affects loudness (intensity), not frequency.',src:'aamc-phys-qpack:Q60'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A stationary sonar emits frequency f toward a reflector approaching at speed u, much less than the wave speed v. The echo\'s frequency shift is approximately:',choices:['fu/v','fu/2v','2fu/v','4fu/v'],ans:2,exp:'The shift happens **twice**: the reflector receives a shifted frequency (moving observer) and then re-emits it as a moving source, so Δf ≈ 2fu/v. This doubling is why Doppler ultrasound and radar use a factor of 2.',src:'aamc-phys-qpack:Q60b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Light in air strikes a flat transparent block at 60° from the normal and refracts to 30° from the normal. What is the block\'s refractive index?',choices:['1.73','2.00','0.58','1.15'],ans:0,exp:'**Snell\'s law** with n(air) = 1 gives n = sin 60° / sin 30° = 0.866 / 0.5 ≈ 1.73. Using the angle ratio (60/30 = 2.00) instead of the sine ratio is the classic trap, and an index below 1 is impossible for a real material.',src:'aamc-phys-qpack:Q61'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'What is the speed of light in glass with a refractive index of 1.5?',choices:['4.5 × 10⁸ m/s','2.0 × 10⁸ m/s','3.0 × 10⁸ m/s','1.5 × 10⁸ m/s'],ans:1,exp:'The refractive index is defined as **n = c/v**, so v = (3.0 × 10⁸ m/s) / 1.5 = 2.0 × 10⁸ m/s. Light always travels slower in a medium than in vacuum, so multiplying by n can never be right.',src:'aamc-phys-qpack:Q61b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A flat mirror must turn a horizontal laser beam by exactly 90°. At what angle to the incoming beam should the mirror surface be set?',choices:['30°','60°','45°','90°'],ans:2,exp:'With the mirror at **45°** to the beam, the angle of incidence (from the normal) is 45° and the angle of reflection is also 45°, so the beam leaves 90° from its original path. A mirror at 90° to the beam sends it straight back (a 180° turn).',src:'aamc-phys-qpack:Q62'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A plane mirror is rotated by an angle θ while the incident beam stays fixed. Through what angle does the reflected beam rotate?',choices:['θ/2','θ','4θ','2θ'],ans:3,exp:'Rotating the mirror by θ rotates its normal by θ, which increases both the angle of incidence and the angle of reflection by θ, so the reflected beam swings through **2θ**. This doubling is why rotating mirrors are used to amplify small angular deflections.',src:'aamc-phys-qpack:Q62b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A light ray in air strikes a glass bead (n = 1.5) at an oblique angle. As it enters the bead, the ray bends:',choices:['toward the normal','away from the normal','parallel to the surface','straight through, unbent'],ans:0,exp:'Entering a medium of **higher refractive index**, light slows down and bends **toward the normal**, as Snell\'s law requires (smaller sine, smaller angle). It bends away from the normal only when passing into a lower-index medium.',src:'aamc-phys-qpack:Q63'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Total internal reflection can occur only when light travels:',choices:['from lower n to higher n beyond the critical angle','from higher n to lower n beyond the critical angle','from higher n to lower n below the critical angle','from lower n to higher n at normal incidence'],ans:1,exp:'**Total internal reflection** needs light heading into a lower-index medium (so it bends away from the normal) at an incidence angle greater than the **critical angle**, sin θc = n₂/n₁. Going into a higher-index medium, a refracted ray always exists.',src:'aamc-phys-qpack:Q63b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A light beam passes obliquely through a flat glass plate with parallel faces. Compared with the incident beam, the emerging beam is:',choices:['bent permanently toward the normal','reflected back toward the source','parallel to it but shifted sideways','unchanged in path and position'],ans:2,exp:'The beam bends toward the normal on entering and by the same amount away from it on leaving, so it emerges **parallel but laterally displaced**. The shift grows with plate thickness and refractive index, which is why inserting a thicker or denser plate moves an image.',src:'aamc-phys-qpack:Q64'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Viewed from directly above, a coin at the bottom of a 2.0 m deep pool (n = 1.33) appears to be at what depth?',choices:['2.7 m','2.0 m','1.0 m','1.5 m'],ans:3,exp:'For near-normal viewing, **apparent depth = real depth / n** = 2.0 / 1.33 ≈ 1.5 m. Rays bend away from the normal as they leave the water, so objects underwater look shallower, not deeper.',src:'aamc-phys-qpack:Q64b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Light of frequency 6.0 × 10¹⁴ Hz travels 1.0 × 10⁻⁴ m in vacuum. About how many wavelengths fit in that distance?',choices:['200','2000','20','50'],ans:0,exp:'First find **λ = c/f** = (3.0 × 10⁸) / (6.0 × 10¹⁴) = 5.0 × 10⁻⁷ m. The number of wavelengths is distance ÷ λ = (1.0 × 10⁻⁴) / (5.0 × 10⁻⁷) = 200.',src:'aamc-phys-qpack:Q65'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'When light passes obliquely from air into glass, which property of the light stays the same?',choices:['Wavelength','Frequency','Speed','Direction of travel'],ans:1,exp:'**Frequency** is set by the source and does not change at a boundary; speed drops to c/n, so wavelength shrinks by the same factor (λ = v/f). The direction changes because of refraction.',src:'aamc-phys-qpack:Q65b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4C',q:'Alpha and beta-minus particles enter a uniform magnetic field moving perpendicular to it. How do their paths compare?',choices:['They curve in the same direction','They pass through undeflected','They curve in opposite directions','They curve parallel to the field'],ans:2,exp:'The magnetic force F = qv × B reverses with the sign of the charge, so the positive **alpha** and negative **beta** curve **in opposite directions**. Beta curves more tightly because it is far lighter, and neutral gamma rays pass straight through.',src:'aamc-phys-qpack:Q66'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Which ranks the three common radiation types from LEAST to MOST penetrating?',choices:['gamma, beta, alpha','beta, alpha, gamma','alpha, gamma, beta','alpha, beta, gamma'],ans:3,exp:'**Alpha** (heavy, +2) is stopped by paper or skin, **beta** by a few mm of aluminum, and **gamma** (uncharged photons) needs thick lead or concrete. Penetration rises as charge and mass fall; ionizing power runs in the reverse order.',src:'aamc-phys-qpack:Q66b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A nucleus emits one alpha particle and then two beta-minus particles. What is the net change in its mass number A and atomic number Z?',choices:['A decreases by 4; Z unchanged','A decreases by 4; Z decreases by 2','A unchanged; Z increases by 2','A decreases by 2; Z decreases by 4'],ans:0,exp:'Alpha decay lowers **A by 4 and Z by 2**; each beta-minus raises **Z by 1** with no change in A. Net: A − 4, Z unchanged, so the product is a lighter **isotope** of the original element (as in U-238 → U-234).',src:'aamc-phys-qpack:Q67'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'An alpha particle is identical to:',choices:['a high-energy electron','a helium-4 nucleus','a high-energy photon','a single proton'],ans:1,exp:'An alpha particle is a **helium-4 nucleus**: 2 protons and 2 neutrons, charge +2. A high-energy electron is a beta-minus particle and a high-energy photon is a gamma ray.',src:'aamc-phys-qpack:Q67b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A radioisotope has a half-life of 8 hours. A dose measured 24 hours after preparation has an activity of 25 mCi. What was its activity when prepared?',choices:['75 mCi','100 mCi','200 mCi','800 mCi'],ans:2,exp:'24 h is **3 half-lives**, so activity fell by 2³ = 8; working backward, 25 mCi × 8 = 200 mCi. Multiplying by the number of half-lives (25 × 3 = 75) treats decay as linear, which it is not.',src:'aamc-phys-qpack:Q68'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Approximately what percentage of a radioactive sample remains after 5 half-lives?',choices:['6%','10%','20%','3%'],ans:3,exp:'The remaining fraction is **(1/2)ⁿ**; for n = 5 that is 1/32 ≈ 3%. A common rule of thumb is that after about 5 to 7 half-lives a sample is essentially gone.',src:'aamc-phys-qpack:Q68b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Radium-226 (Z = 88) emits 5 alpha particles and 4 beta-minus particles in a decay series. What is the final product?',choices:['Lead-206 (Z = 82)','Mercury-206 (Z = 80)','Lead-210 (Z = 82)','Polonium-206 (Z = 84)'],ans:0,exp:'Mass number: 226 − 5 × 4 = 206 (beta does not change A). Atomic number: 88 − 5 × 2 + 4 × 1 = 82, which is **lead**. Forgetting the betas would give Z = 78, and miscounting alphas changes A.',src:'aamc-phys-qpack:Q69'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'What happens inside the nucleus during beta-minus decay?',choices:['A proton becomes a neutron','A neutron becomes a proton','A neutron is ejected','Two protons are ejected'],ans:1,exp:'In **beta-minus decay** a neutron converts to a proton, emitting an electron and an antineutrino, so Z rises by 1 while A stays the same. A proton becoming a neutron describes positron emission or electron capture.',src:'aamc-phys-qpack:Q69b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A solid ball stays at rest fully submerged in the middle of a liquid, neither rising nor sinking. Its density must be:',choices:['less than the liquid\'s density','greater than the liquid\'s density','equal to the liquid\'s density','unrelated to the liquid\'s density'],ans:2,exp:'A fully submerged object feels a buoyant force ρ(fluid)Vg and a weight ρ(object)Vg; they balance only when the **densities are equal** (neutral buoyancy). A less dense object floats partly above the surface and a denser one sinks.',src:'aamc-phys-qpack:Q70'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A fully submerged rock is lowered deeper into a lake (treat water as incompressible). The buoyant force on it:',choices:['increases with depth','decreases with depth','drops to zero','stays the same'],ans:3,exp:'By **Archimedes\' principle**, buoyant force equals the weight of displaced fluid, ρgV. Pressure grows with depth, but the pressure difference between the rock\'s top and bottom, and so the buoyant force, does not change once it is fully submerged.',src:'aamc-phys-qpack:Q70b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'What is the pressure difference between two points in still water that differ in depth by 0.50 m? (ρ = 1000 kg/m³, g = 9.8 m/s²)',choices:['4.9 × 10³ Pa','4.9 × 10² Pa','4.9 × 10⁴ Pa','9.8 × 10³ Pa'],ans:0,exp:'**ΔP = ρgΔh** = 1000 × 9.8 × 0.50 = 4.9 × 10³ Pa. Only the vertical depth difference matters, not the shape of the container or atmospheric pressure (which cancels).',src:'aamc-phys-qpack:Q71'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'The absolute pressure 10 m below the surface of a freshwater lake is approximately:',choices:['1 atm','2 atm','10 atm','11 atm'],ans:1,exp:'Each 10 m of water adds about ρgh ≈ 1.0 × 10⁵ Pa, or about **1 atm**, to the atmospheric pressure of 1 atm at the surface, so the total is about 2 atm. The gauge pressure there is about 1 atm.',src:'aamc-phys-qpack:Q71b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A wooden block with density 600 kg/m³ floats in water (1000 kg/m³). What fraction of its volume is ABOVE the surface?',choices:['0.60','0.25','0.80','0.40'],ans:3,exp:'For a floating object, **fraction submerged = ρ(object)/ρ(fluid)** = 600/1000 = 0.60, so 0.40 sits above the water. Answering 0.60 gives the submerged fraction rather than the exposed one.',src:'aamc-phys-qpack:Q72'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'An object floats in water with three-quarters of its volume submerged. What is its density?',choices:['250 kg/m³','1333 kg/m³','750 kg/m³','1000 kg/m³'],ans:2,exp:'Since the submerged fraction equals ρ(object)/ρ(water), ρ = 0.75 × 1000 = **750 kg/m³**. Any floating object must be less dense than the fluid, which rules out values at or above 1000 kg/m³.',src:'aamc-phys-qpack:Q72b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'Water drains from a small hole 0.80 m below the surface of an open tank. About how fast does it exit? (g = 9.8 m/s²)',choices:['4.0 m/s','2.8 m/s','8.0 m/s','16 m/s'],ans:0,exp:'**Torricelli\'s law**, from Bernoulli\'s equation, gives v = √(2gh) = √(2 × 9.8 × 0.80) ≈ 4.0 m/s, the same speed as an object falling freely from the water surface to the hole.',src:'aamc-phys-qpack:Q73'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'For a small hole in the side of an open tank, the exit speed of the liquid depends on:',choices:['the area of the hole','the depth of the hole','the density of the liquid','the volume of the tank'],ans:1,exp:'Torricelli\'s result **v = √(2gh)** contains only g and the **depth** below the surface. Density cancels in Bernoulli\'s equation, and the hole\'s area affects the volume flow rate (Q = Av), not the speed.',src:'aamc-phys-qpack:Q73b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 3.0 kg load is raised 2.0 m at constant speed with an ideal pulley system of mechanical advantage 4. How much work is done on the load? (g = 10 m/s²)',choices:['15 J','240 J','60 J','30 J'],ans:2,exp:'At constant speed the work done equals the gain in PE, **mgh** = 3.0 × 10 × 2.0 = 60 J. The pulley cuts the force to one-quarter, but the rope must be pulled 4 times as far, so the work is unchanged.',src:'aamc-phys-qpack:Q74'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'An ideal pulley system with 4 rope segments supporting the load lifts a 200 N weight at constant speed. What effort force is needed?',choices:['200 N','800 N','25 N','50 N'],ans:3,exp:'The **mechanical advantage** equals the number of supporting segments, so effort = 200 N / 4 = 50 N. The trade-off is distance: the effort end moves 4 times farther than the load rises.',src:'aamc-phys-qpack:Q74b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A sound wave reflects off a surface moving toward the source. Which property of the reflected wave traveling through still air is the SAME as the incident wave\'s?',choices:['Speed','Frequency','Wavelength','Intensity'],ans:0,exp:'The **speed of sound** is set by the medium (air temperature and properties), not by the source or reflector. The moving reflector Doppler-shifts the frequency and wavelength, and partial absorption lowers the intensity.',src:'aamc-phys-qpack:Q75'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A 640 Hz source moves at 20 m/s toward a stationary listener. What frequency does the listener hear? (speed of sound = 340 m/s)',choices:['600 Hz','680 Hz','640 Hz','720 Hz'],ans:1,exp:'For an approaching source, **f\' = f · v/(v − vs)** = 640 × 340/320 = 680 Hz. Approach always raises the observed frequency; subtracting in the numerator instead would wrongly lower it.',src:'aamc-phys-qpack:Q75b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 2.0 N load sits 0.30 m from a lever\'s pivot. What force, applied perpendicular to the lever 0.60 m from the pivot on the other side, balances it?',choices:['4.0 N','2.0 N','1.0 N','0.5 N'],ans:2,exp:'Balancing torques, **F₁r₁ = F₂r₂**: F × 0.60 = 2.0 × 0.30, so F = 1.0 N. A longer lever arm needs proportionally less force; the 4.0 N trap inverts the ratio.',src:'aamc-phys-qpack:Q76'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 10 N force is applied 0.50 m from a pivot at an angle of 30° to the lever arm. What torque does it produce?',choices:['4.3 N·m','5.0 N·m','0 N·m','2.5 N·m'],ans:3,exp:'**τ = rF sin θ**, where θ is the angle between r and F: 0.50 × 10 × sin 30° = 2.5 N·m. Using cos 30° gives 4.3 N·m, and ignoring the angle gives the maximum, 5.0 N·m, which applies only to a perpendicular force.',src:'aamc-phys-qpack:Q76b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'To find the relative refractive index of two media using Snell\'s law, a student must measure:',choices:['the incidence and refraction angles','the incidence and reflection angles','the reflection angle and frequency','the wavelength and beam intensity'],ans:0,exp:'**Snell\'s law**, n₁ sin θ₁ = n₂ sin θ₂, gives n₂/n₁ = sin θ₁ / sin θ₂, so only the **incidence** and **refraction** angles are needed. The reflection angle always equals the incidence angle and carries no extra information.',src:'aamc-phys-qpack:Q77'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Angles of incidence, reflection and refraction are conventionally measured relative to:',choices:['the surface itself','the normal to the surface','the incident beam','the horizontal'],ans:1,exp:'All three angles are measured from the **normal**, a line perpendicular to the surface at the point of contact. Measuring from the surface gives the complement of the correct angle, a common source of Snell\'s-law errors.',src:'aamc-phys-qpack:Q77b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A point charge produces an electric field E at a given point. If the charge is tripled and the distance to the point is halved, the new field is:',choices:['6E','3E/4','12E','1.5E'],ans:2,exp:'**E = kq/r²**: tripling q multiplies E by 3, and halving r multiplies it by 2² = 4, giving 12E. Forgetting to square the distance gives 6E.',src:'aamc-phys-qpack:Q78'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'Two point charges exert a force F on each other. If both charges are doubled and their separation is also doubled, the force becomes:',choices:['2F','4F','F/2','F'],ans:3,exp:'**F = kq₁q₂/r²**: doubling both charges multiplies F by 4, and doubling r divides it by 4, so the force is unchanged. Coulomb\'s law has the same inverse-square form as gravity.',src:'aamc-phys-qpack:Q78b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A crate is slid 5 m across a level floor at constant speed. If it is slid the same distance at twice the speed, the work done by kinetic friction:',choices:['stays the same','doubles','quadruples','halves'],ans:0,exp:'Kinetic friction **f = μk N** does not depend on speed, so its work, f × d, is the same over the same distance. Doubling speed shortens the time, not the friction force.',src:'aamc-phys-qpack:Q79'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'An 8.0 kg box slides 5.0 m across a level floor with μk = 0.25. How much work does friction do on the box? (g = 10 m/s²)',choices:['−400 J','−100 J','−20 J','−40 J'],ans:1,exp:'f = μk mg = 0.25 × 8.0 × 10 = 20 N, so **W = −fd** = −20 × 5.0 = −100 J. The work is negative because friction acts opposite the displacement, converting kinetic energy into thermal energy.',src:'aamc-phys-qpack:Q79b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A cart\'s speed increases uniformly from 0 to 12 m/s over 4.0 s. How far does it travel in that time?',choices:['48 m','12 m','24 m','3.0 m'],ans:2,exp:'Distance is the **area under the speed–time graph**: a triangle of ½ × 4.0 s × 12 m/s = 24 m. Multiplying the final speed by the time (48 m) overcounts, because the cart was slower earlier; 3.0 m/s² is the slope (acceleration).',src:'aamc-phys-qpack:Q80'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'The slope of a position–time graph gives an object\'s:',choices:['acceleration','displacement','net force','velocity'],ans:3,exp:'Slope is change in position over change in time, which is **velocity**. On a velocity–time graph the slope gives acceleration and the area gives displacement.',src:'aamc-phys-qpack:Q80b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A block slides across a level floor with μk = 0.30. What is the magnitude of its acceleration? (g = 10 m/s²)',choices:['3.0 m/s²','0.30 m/s²','10 m/s²','13 m/s²'],ans:0,exp:'Friction is the only horizontal force, so ma = μk mg and **a = μk g** = 0.30 × 10 = 3.0 m/s², directed opposite the motion. The mass cancels, so heavy and light blocks decelerate equally.',src:'aamc-phys-qpack:Q81'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A puck moving at 6.0 m/s decelerates uniformly at 3.0 m/s² on a rough floor. How far does it slide before stopping?',choices:['12 m','6.0 m','2.0 m','3.0 m'],ans:1,exp:'Using **v² = v₀² + 2aΔx** with v = 0: Δx = v₀²/(2a) = 36/6.0 = 6.0 m. The 2.0 value is the stopping time in seconds (v₀/a), not the distance.',src:'aamc-phys-qpack:Q81b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A block slides down a ramp of fixed length. If the ramp is made steeper, the normal force on the block:',choices:['increases','stays the same','decreases','becomes equal to mg'],ans:2,exp:'The normal force on an incline is **mg cos θ**, which falls as θ rises, so kinetic friction (μk N) and the work it does over the same length also fall. The normal force equals mg only on a level surface.',src:'aamc-phys-qpack:Q82'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'What is the component of gravity acting along a 30° incline on a 10 kg block? (g = 10 m/s²)',choices:['87 N','100 N','25 N','50 N'],ans:3,exp:'The along-slope component is **mg sin θ** = 10 × 10 × 0.5 = 50 N. The 87 N value is mg cos θ, the component perpendicular to the slope that the normal force balances.',src:'aamc-phys-qpack:Q82b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'Water flows at 1.5 m/s through a pipe of cross-sectional area 6.0 cm² into a section of area 2.0 cm². What is its speed in the narrow section?',choices:['4.5 m/s','0.50 m/s','3.0 m/s','13.5 m/s'],ans:0,exp:'The **continuity equation**, A₁v₁ = A₂v₂, gives v₂ = 1.5 × 6.0/2.0 = 4.5 m/s. An incompressible fluid must speed up where the pipe narrows, so a slower answer is impossible.',src:'aamc-phys-qpack:Q83'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'Compared with the wide section of a horizontal pipe, fluid in a narrow section has:',choices:['higher speed and higher pressure','higher speed and lower pressure','lower speed and lower pressure','lower speed and higher pressure'],ans:1,exp:'Continuity makes the fluid **speed up** in the narrow section, and **Bernoulli\'s equation** (P + ½ρv² constant at equal height) then requires lower pressure. This is the Venturi effect.',src:'aamc-phys-qpack:Q83b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'In an electromagnetic flowmeter, blood moving at 0.50 m/s crosses a 0.20 T field in a vessel 1.0 cm wide. What voltage appears across the vessel?',choices:['10 mV','0.10 mV','1.0 mV','25 mV'],ans:2,exp:'At equilibrium the electric and magnetic forces on the ions balance, qE = qvB, so **V = vBd** = 0.50 × 0.20 × 0.010 = 1.0 × 10⁻³ V = 1.0 mV. A stronger magnet or faster flow gives a larger voltage.',src:'aamc-phys-qpack:Q84'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'In a velocity selector with crossed fields E = 2.0 × 10⁴ V/m and B = 0.10 T, at what speed do charged particles pass straight through?',choices:['2.0 × 10³ m/s','5.0 × 10⁻⁶ m/s','2.0 × 10⁴ m/s','2.0 × 10⁵ m/s'],ans:3,exp:'Particles go undeflected when the forces balance, qE = qvB, so **v = E/B** = 2.0 × 10⁴ / 0.10 = 2.0 × 10⁵ m/s. The result does not depend on charge or mass; inverting the ratio (B/E) gives a nonsensically small speed.',src:'aamc-phys-qpack:Q84b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'Fluid flows at 0.50 m/s through a tube of inner diameter 2.0 cm. What is the volume flow rate?',choices:['1.6 × 10⁻⁴ m³/s','6.3 × 10⁻⁴ m³/s','3.1 × 10⁻⁴ m³/s','1.6 × 10⁻² m³/s'],ans:0,exp:'**Q = Av** with A = π(d/2)² = π(0.010 m)² = 3.1 × 10⁻⁴ m², so Q = 3.1 × 10⁻⁴ × 0.50 ≈ 1.6 × 10⁻⁴ m³/s. Using the diameter instead of the radius in the area quadruples the answer.',src:'aamc-phys-qpack:Q85'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'At the same volume flow rate, a tube\'s radius is doubled. The flow speed becomes:',choices:['one-half','one-fourth','twice','four times'],ans:1,exp:'Area scales as **r²**, so doubling the radius makes the area 4 times larger, and with Q = Av fixed, the speed drops to one-fourth. Halving is the trap of scaling with radius rather than area.',src:'aamc-phys-qpack:Q85b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A charged particle moves through a uniform magnetic field, and the magnetic force is the only force on it. Its speed:',choices:['increases steadily','decreases steadily','remains constant','oscillates periodically'],ans:2,exp:'The magnetic force **F = qv × B** is always perpendicular to the velocity, so it does **no work** and cannot change kinetic energy. It changes only the direction of motion, producing circular or helical paths.',src:'aamc-phys-qpack:Q86'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A proton moves in the +x direction through a magnetic field pointing in the +y direction. In which direction is the magnetic force on it?',choices:['−z','+y','−x','+z'],ans:3,exp:'By the **right-hand rule**, x̂ × ŷ = +ẑ, so a positive charge feels a force in +z. An electron would feel the force in −z, and the force is never along v or B.',src:'aamc-phys-qpack:Q86b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A block on a table is tied by a string over a pulley to a hanging mass. As the hanging mass falls, the kinetic energy of the sliding block comes from:',choices:['the hanging mass\'s gravitational PE','the table\'s normal force on the block','the block\'s own gravitational PE','the pulley\'s rotational energy'],ans:0,exp:'Only the **hanging mass** loses height, so its gravitational potential energy supplies the kinetic energy of both masses (minus any losses to friction). The normal force is perpendicular to the block\'s motion and does no work.',src:'aamc-phys-qpack:Q87'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 3.0 kg block on a frictionless table is connected over an ideal pulley to a hanging 1.0 kg mass. What is the system\'s acceleration? (g = 10 m/s²)',choices:['3.3 m/s²','2.5 m/s²','10 m/s²','7.5 m/s²'],ans:1,exp:'The only unbalanced force is the hanging weight, 1.0 × 10 = 10 N, which accelerates the **total mass** of 4.0 kg: a = 10/4.0 = 2.5 m/s². Dividing by the block\'s mass alone gives 3.3 m/s².',src:'aamc-phys-qpack:Q87b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A brick sliding on its wide face is turned to slide on its narrow face over the same surface. The kinetic friction force:',choices:['increases','decreases','stays the same','drops to zero'],ans:2,exp:'In the standard model, friction **f = μN** depends only on the coefficient and the normal force, not on contact area. The brick\'s weight and the surfaces are unchanged, so the friction force is unchanged.',src:'aamc-phys-qpack:Q88'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 5.0 kg box slides on a floor (μk = 0.40) while someone also pushes straight down on it with 20 N. What is the kinetic friction force? (g = 10 m/s²)',choices:['20 N','8.0 N','12 N','28 N'],ans:3,exp:'The normal force rises to mg + 20 N = 70 N, so **f = μk N** = 0.40 × 70 = 28 N. Using only the weight gives 20 N; extra downward pushes raise friction because they raise N.',src:'aamc-phys-qpack:Q88b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A constant horizontal force larger than kinetic friction keeps pulling a box after it starts sliding. The box\'s speed:',choices:['increases linearly with time','increases with time squared','stays constant over time','decreases linearly with time'],ans:0,exp:'Kinetic friction is constant and smaller than the pull, so the **net force is constant**, giving constant acceleration and v = v₀ + at. Position, not speed, grows with t².',src:'aamc-phys-qpack:Q89'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 20 kg box rests on a floor with μs = 0.50 and μk = 0.30. What minimum horizontal force starts it moving? (g = 10 m/s²)',choices:['60 N','100 N','200 N','40 N'],ans:1,exp:'Starting motion requires overcoming **maximum static friction**, μs mg = 0.50 × 200 = 100 N. Once sliding, only μk mg = 60 N is needed to keep it moving at constant speed, since μk < μs.',src:'aamc-phys-qpack:Q89b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A block on an adjustable ramp just begins to slip when the ramp reaches angle θ. The coefficient of static friction equals:',choices:['sin θ','cos θ','tan θ','1/tan θ'],ans:2,exp:'At the slipping point, mg sin θ = μs mg cos θ, so **μs = tan θ**. Measuring this angle is a simple way to find μs, and the result does not depend on the block\'s mass.',src:'aamc-phys-qpack:Q90'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A block slides down a 30° incline at constant velocity. What is the coefficient of kinetic friction?',choices:['0.50','0.87','1.73','0.58'],ans:3,exp:'Constant velocity means zero net force, so mg sin θ = μk mg cos θ and **μk = tan 30°** ≈ 0.58. The 0.50 value is sin 30°, which ignores the normal-force component.',src:'aamc-phys-qpack:Q90b'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'A fully submerged object feels a 4.0 N buoyant force in oil of density 800 kg/m³. What buoyant force acts on it fully submerged in a liquid of density 1200 kg/m³?',choices:['6.0 N','2.7 N','4.0 N','4.8 N'],ans:0,exp:'Buoyant force **F = ρ(fluid)gV**; with the same submerged volume, F scales with fluid density: 4.0 × 1200/800 = 6.0 N. Inverting the ratio gives 2.7 N.',src:'aamc-phys-qpack:Q91'},
  {s:'Fluids',disc:'physics',aamc:'4B',q:'An object weighing 50 N in air has a volume of 2.0 × 10⁻³ m³. What is its apparent weight when fully submerged in water? (g = 10 m/s²)',choices:['20 N','30 N','50 N','70 N'],ans:1,exp:'Buoyant force = ρgV = 1000 × 10 × 2.0 × 10⁻³ = 20 N, so **apparent weight = true weight − buoyant force** = 50 − 20 = 30 N. Adding the buoyant force instead gives 70 N.',src:'aamc-phys-qpack:Q91b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A ball is thrown straight up with the same speed on Earth and on a planet with one-quarter of Earth\'s gravity. On the planet, the time to return to the hand is:',choices:['twice as long','the same','4 times as long','one-fourth as long'],ans:2,exp:'The round-trip time of a vertical throw is **t = 2v₀/g**, so it scales as 1/g: one-quarter the gravity means 4 times the time. The maximum height, v₀²/2g, is also 4 times greater.',src:'aamc-phys-qpack:Q92'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A ball is launched straight up at 20 m/s. How high does it rise? (g = 10 m/s², ignore air resistance)',choices:['40 m','10 m','2.0 m','20 m'],ans:3,exp:'At the top v = 0, so **h = v₀²/(2g)** = 400/20 = 20 m. Equivalently, all the initial KE becomes PE: ½mv₀² = mgh. Forgetting the factor of 2 gives 40 m.',src:'aamc-phys-qpack:Q92b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Sound from a room is much quieter on the other side of a solid wall mainly because:',choices:['energy is reflected and absorbed at the wall','the wall lowers the sound\'s frequency','the wave speed drops in the air beyond','the wall shortens the sound\'s wavelength'],ans:0,exp:'At the wall\'s boundaries much of the wave\'s energy is **reflected** (impedance mismatch) and some is **absorbed** as heat, so less is transmitted and intensity drops. Frequency is unchanged at a boundary, and the speed in the air beyond is the same as before.',src:'aamc-phys-qpack:Q93'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'If a wall reduces sound intensity by a factor of 1000, by how much does the sound level drop?',choices:['3 dB','30 dB','10 dB','60 dB'],ans:1,exp:'Sound level is **β = 10 log(I/I₀)**, so each factor of 10 in intensity is 10 dB; a factor of 1000 = 10³ is 30 dB. A drop of 3 dB corresponds to only halving the intensity.',src:'aamc-phys-qpack:Q93b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'5E',q:'An experiment to measure a substance\'s heat of fusion must measure the heat absorbed while:',choices:['a liquid boils at its boiling point','a liquid warms below its boiling point','a solid melts at its melting point','a vapor condenses at its boiling point'],ans:2,exp:'The **heat of fusion** is the energy per unit mass to melt a solid (or released on freezing) at constant temperature. Boiling and condensing measure the heat of vaporization, and warming a liquid measures specific heat.',src:'aamc-phys-qpack:Q94'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'5E',q:'How much heat is needed to melt 0.20 kg of ice already at 0 °C? (Lf = 334 kJ/kg, Lv = 2260 kJ/kg)',choices:['452 kJ','1670 kJ','33 kJ','67 kJ'],ans:3,exp:'**Q = mLf** = 0.20 × 334 ≈ 67 kJ, and the temperature stays at 0 °C throughout the phase change. Using the heat of vaporization gives 452 kJ, and dividing instead of multiplying gives 1670 kJ.',src:'aamc-phys-qpack:Q94b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A uniform 1.0 m stick of mass 0.60 kg is balanced on a pivot at its 40 cm mark by a mass hung at the 10 cm mark. What is that mass?',choices:['0.20 kg','0.60 kg','1.8 kg','0.15 kg'],ans:0,exp:'The stick\'s weight acts at its **center of mass** (50 cm), 10 cm from the pivot; the hanging mass is 30 cm away on the other side. Balancing torques: m × 30 = 0.60 × 10, so m = 0.20 kg. Ignoring the stick\'s own weight leaves nothing to balance.',src:'aamc-phys-qpack:Q95'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 2.0 kg mass sits at x = 0 and a 6.0 kg mass sits at x = 4.0 m. Where is their center of mass?',choices:['x = 2.0 m','x = 3.0 m','x = 1.0 m','x = 1.3 m'],ans:1,exp:'**x(cm) = Σmx / Σm** = (2.0 × 0 + 6.0 × 4.0)/8.0 = 3.0 m. The center of mass lies closer to the heavier mass; 1.0 m wrongly places it nearer the lighter one.',src:'aamc-phys-qpack:Q95b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'To double the fundamental frequency of a stretched string without changing its length or mass, the tension must be multiplied by:',choices:['2','√2','4','8'],ans:2,exp:'For a string, **f = (1/2L)√(T/μ)**, so f ∝ √T and doubling f requires 2² = 4 times the tension. Doubling the tension raises f only by √2.',src:'aamc-phys-qpack:Q96'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A string under 100 N of tension has a linear mass density of 0.010 kg/m. What is the speed of waves on it?',choices:['10 m/s','10,000 m/s','1000 m/s','100 m/s'],ans:3,exp:'Wave speed on a string is **v = √(T/μ)** = √(100/0.010) = √10,000 = 100 m/s. Forgetting the square root gives 10,000 m/s.',src:'aamc-phys-qpack:Q96b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A guitar string is replaced by a heavier string of the same length under the same tension. Its fundamental frequency becomes:',choices:['lower, since wave speed drops','higher, since wave speed rises','unchanged, since length sets it','higher, since wavelength shrinks'],ans:0,exp:'Greater **mass per unit length** μ lowers the wave speed √(T/μ); the fundamental wavelength stays 2L, so f = v/2L falls. That is why bass strings are thick and heavy.',src:'aamc-phys-qpack:Q97'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'For a string fixed at both ends with length L, the wavelength of the fundamental standing wave is:',choices:['L','2L','L/2','4L'],ans:1,exp:'The fundamental has nodes at both ends and one antinode in the middle, so the string holds half a wavelength: **λ = 2L**. The 4L value applies to a pipe closed at one end.',src:'aamc-phys-qpack:Q97b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'What is the frequency of the note one octave above a 330 Hz tone?',choices:['165 Hz','495 Hz','660 Hz','990 Hz'],ans:2,exp:'An **octave** is a 2:1 frequency ratio, so one octave up is 2 × 330 = 660 Hz and one octave down is 165 Hz. Adding half the frequency (495 Hz) gives a perfect fifth instead.',src:'aamc-phys-qpack:Q98'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'The perceived pitch of a sound is determined mainly by its:',choices:['amplitude','speed','intensity','frequency'],ans:3,exp:'**Pitch** corresponds to frequency, while loudness corresponds to amplitude and intensity. The speed of sound depends on the medium, not on pitch.',src:'aamc-phys-qpack:Q98b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A perfect fifth corresponds to a 3:2 frequency ratio. What frequency is a perfect fifth above 200 Hz?',choices:['300 Hz','400 Hz','133 Hz','250 Hz'],ans:0,exp:'Going up a fifth multiplies by **3/2**: 200 × 1.5 = 300 Hz. Going down a fifth multiplies by 2/3 (133 Hz), and doubling gives an octave (400 Hz).',src:'aamc-phys-qpack:Q99'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A string\'s fundamental frequency is 110 Hz. What is the frequency of its third harmonic?',choices:['220 Hz','330 Hz','165 Hz','440 Hz'],ans:1,exp:'For a string, harmonics are whole-number multiples of the fundamental, **fₙ = nf₁**, so the third harmonic is 3 × 110 = 330 Hz. The third and second harmonics (330 and 220 Hz) form a 3:2 ratio, a perfect fifth.',src:'aamc-phys-qpack:Q99b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'In a simple model of fission, what drives the two newly formed fragments apart?',choices:['Strong-force attraction between them','Gravitational attraction between them','Coulomb repulsion between them','Magnetic attraction between them'],ans:2,exp:'Both fragments carry large **positive charges**, and once they separate beyond the short range of the strong force, their **Coulomb repulsion** pushes them apart at high kinetic energy. The strong force is attractive and acts only over about a nucleon diameter.',src:'aamc-phys-qpack:Q100'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Fission of a very heavy nucleus releases energy because the fragments have:',choices:['lower binding energy per nucleon','greater total mass','more total protons','greater binding energy per nucleon'],ans:3,exp:'**Binding energy per nucleon** peaks near iron-56, so splitting a heavy nucleus into mid-sized fragments moves toward the peak and releases the difference as energy. Correspondingly, the products have slightly less total mass (E = Δmc²).',src:'aamc-phys-qpack:Q100b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A nucleus at rest splits into two fragments with masses m and 3m. How do the forces they exert on each other compare?',choices:['equal in magnitude','3 times larger on the lighter','3 times larger on the heavier','9 times larger on the lighter'],ans:0,exp:'By **Newton\'s third law**, the forces are equal and opposite whatever the masses. The lighter fragment has 3 times the acceleration and speed, while the two momenta are equal in magnitude.',src:'aamc-phys-qpack:Q101'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A nucleus at rest splits into fragments of mass m and 3m. What is the ratio of the lighter fragment\'s kinetic energy to the heavier one\'s?',choices:['9','3','1','1/3'],ans:1,exp:'Momentum conservation gives equal momentum magnitudes, and **KE = p²/2m**, so KE is inversely proportional to mass: the lighter fragment gets 3 times the KE. Using the 3:1 speed ratio squared, without the 1:3 mass ratio, gives the trap answer of 9.',src:'aamc-phys-qpack:Q101b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Why are very large nuclei, such as uranium, unstable?',choices:['The strong force is long-range; proton repulsion is short-range','Gravity between nucleons overcomes the strong force','The strong force is short-range; proton repulsion is long-range','The strong force turns repulsive at large nuclear sizes'],ans:2,exp:'The **strong force** binds only nearest neighbors, but **Coulomb repulsion** acts between every pair of protons across the whole nucleus. As nuclei grow, repulsion increases faster than binding, making very heavy nuclei prone to alpha decay or fission.',src:'aamc-phys-qpack:Q102'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'For stable heavy nuclei, the neutron-to-proton ratio is approximately:',choices:['1.0','0.5','3.0','1.5'],ans:3,exp:'Heavy stable nuclei need **extra neutrons** (N/Z ≈ 1.5), which add strong-force attraction without adding Coulomb repulsion. Light stable nuclei, such as C-12 and O-16, have N/Z ≈ 1.',src:'aamc-phys-qpack:Q102b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'The distance between two point charges is tripled. The electrostatic force between them becomes:',choices:['1/9 as large','1/3 as large','1/27 as large','1/6 as large'],ans:0,exp:'Coulomb\'s law is an **inverse-square law**, F ∝ 1/r², so tripling r divides the force by 3² = 9. A plot of F against r falls steeply, not linearly.',src:'aamc-phys-qpack:Q103'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'The distance from a point charge is doubled. The electric potential at that point becomes:',choices:['one-fourth as large','one-half as large','twice as large','unchanged'],ans:1,exp:'Electric potential from a point charge is **V = kq/r**, which falls as 1/r, so doubling r halves V. The field (kq/r²) and force fall as 1/r², which is why one-fourth is tempting.',src:'aamc-phys-qpack:Q103b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Carbon-14 decays to nitrogen-14. What particle is emitted?',choices:['A positron','An alpha particle','An electron','A neutron'],ans:2,exp:'Z rises from 6 to 7 while A stays 14, which is **beta-minus decay**: a neutron becomes a proton and an **electron** (plus an antineutrino) is emitted. Positron emission would lower Z, and alpha emission would lower A by 4.',src:'aamc-phys-qpack:Q104'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'In positron (beta-plus) emission, the daughter nucleus\'s atomic number:',choices:['increases by 1','decreases by 2','stays the same','decreases by 1'],ans:3,exp:'In **positron emission** a proton becomes a neutron, emitting a positron and a neutrino, so Z decreases by 1 and A is unchanged. Beta-minus decay does the opposite, raising Z by 1.',src:'aamc-phys-qpack:Q104b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A sample now contains 500 atoms of an isotope with a 2000-year half-life. How many atoms of it were present 8000 years ago?',choices:['8000','4000','2000','16,000'],ans:0,exp:'8000 years is **4 half-lives**, so the original amount was 2⁴ = 16 times larger: 500 × 16 = 8000 atoms. Multiplying by the number of half-lives (500 × 4 = 2000) treats decay as linear.',src:'aamc-phys-qpack:Q105'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Carbon-14 has a half-life of about 5,700 years. A bone retains one-quarter of its original C-14. About how old is it?',choices:['5,700 years','11,400 years','17,100 years','22,800 years'],ans:1,exp:'One-quarter remaining means **2 half-lives** have passed: 2 × 5,700 ≈ 11,400 years. One-eighth would correspond to 3 half-lives (about 17,100 years).',src:'aamc-phys-qpack:Q105b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'An electron (m = 9.1 × 10⁻³¹ kg) moves at 2.0 × 10⁷ m/s. What is its kinetic energy?',choices:['3.6 × 10⁻¹⁶ J','9.1 × 10⁻²⁴ J','1.8 × 10⁻¹⁶ J','1.8 × 10⁻²³ J'],ans:2,exp:'**KE = ½mv²** = 0.5 × 9.1 × 10⁻³¹ × (2.0 × 10⁷)² = 0.5 × 9.1 × 10⁻³¹ × 4.0 × 10¹⁴ ≈ 1.8 × 10⁻¹⁶ J. Dropping the ½ doubles the answer, and not squaring v gives about 10⁻²³ J.',src:'aamc-phys-qpack:Q106'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'An electron starting from rest is accelerated through a potential difference of 100 V. How much kinetic energy does it gain?',choices:['1.6 × 10⁻¹⁹ J','1.6 × 10⁻²¹ J','6.2 × 10⁻¹⁷ J','1.6 × 10⁻¹⁷ J'],ans:3,exp:'**ΔKE = qΔV** = (1.6 × 10⁻¹⁹ C)(100 V) = 1.6 × 10⁻¹⁷ J, which is 100 eV. One electron-volt (1.6 × 10⁻¹⁹ J) is the energy gained across just 1 V.',src:'aamc-phys-qpack:Q106b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'What is the energy of a photon of wavelength 600 nm? (h = 6.63 × 10⁻³⁴ J·s, c = 3.0 × 10⁸ m/s)',choices:['3.3 × 10⁻¹⁹ J','1.1 × 10⁻²⁷ J','3.3 × 10⁻¹⁰ J','1.2 × 10⁻³¹ J'],ans:0,exp:'**E = hc/λ** = (6.63 × 10⁻³⁴ × 3.0 × 10⁸)/(6.0 × 10⁻⁷ m) ≈ 3.3 × 10⁻¹⁹ J, about 2 eV for visible light. Leaving λ in nanometers gives 3.3 × 10⁻¹⁰ J, and h/λ is the photon\'s momentum, not its energy.',src:'aamc-phys-qpack:Q107'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'A scintillation detector registers ionizing radiation by:',choices:['measuring the heat the radiation deposits','converting absorbed energy into light flashes','collecting ions in a gas-filled tube','sensing the radiation\'s magnetic field'],ans:1,exp:'A **scintillator** absorbs radiation and re-emits the energy as brief flashes of visible light, which a photomultiplier converts to an electrical signal. Collecting ions in a gas-filled tube describes a Geiger counter.',src:'aamc-phys-qpack:Q107b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A sled slides down a snowy hill with friction. Which energy conversion takes place?',choices:['KE into gravitational PE and thermal energy','Gravitational PE entirely into KE','Gravitational PE into KE and thermal energy','Thermal energy into KE and gravitational PE'],ans:2,exp:'Losing height releases **gravitational PE**; part becomes **kinetic energy** and part becomes **thermal energy** through friction. Only on a frictionless slope would all the PE become KE.',src:'aamc-phys-qpack:Q108'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 20 kg sled starts from rest 5.0 m above the bottom of a hill and reaches the bottom at 6.0 m/s. How much energy was converted to thermal energy? (g = 10 m/s²)',choices:['360 J','1000 J','1360 J','640 J'],ans:3,exp:'Initial PE = mgh = 20 × 10 × 5.0 = 1000 J; final KE = ½ × 20 × 6.0² = 360 J. By **energy conservation**, the missing 640 J went to thermal energy via friction.',src:'aamc-phys-qpack:Q108b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A box slides the full length of a 10 m ramp that rises 6.0 m, against a constant 15 N kinetic friction force. How much energy does friction remove?',choices:['150 J','90 J','240 J','60 J'],ans:0,exp:'Work by friction is **force × distance along the path**: 15 N × 10 m = 150 J. Multiplying by the height (90 J) wrongly treats friction like gravity, whose work depends only on vertical drop.',src:'aamc-phys-qpack:Q109'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'The work done by which of these forces depends on the path taken between two points?',choices:['Gravity','Kinetic friction','Spring force','Electrostatic force'],ans:1,exp:'**Kinetic friction** is a **nonconservative** force: a longer path means more work and more energy lost as heat. Gravity, spring and electrostatic forces are conservative, so their work depends only on the start and end points.',src:'aamc-phys-qpack:Q109b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A 30 N horizontal pull keeps a 20 kg crate sliding at constant speed across a level floor. What is μk? (g = 10 m/s²)',choices:['1.5','0.30','0.15','6.7'],ans:2,exp:'Constant speed means the pull equals kinetic friction, so **μk = f/N** = 30/(20 × 10) = 0.15. Dividing by the mass instead of the weight (normal force) gives 1.5.',src:'aamc-phys-qpack:Q110'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'What are the units of the coefficient of friction?',choices:['Newtons','Newtons per kilogram','Kilograms','It is dimensionless'],ans:3,exp:'μ is a ratio of two forces (**friction / normal force**), so the newtons cancel and it is dimensionless. Most values fall between about 0 and 1, though some rubber surfaces exceed 1.',src:'aamc-phys-qpack:Q110b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'A child slides from rest down a frictionless slide. If the starting height is cut to one-quarter, the speed at the bottom becomes:',choices:['one-half as large','one-quarter as large','one-sixteenth as large','the same as before'],ans:0,exp:'From mgh = ½mv², **v = √(2gh)**, so v scales as √h: one-quarter the height gives √(1/4) = one-half the speed. Likewise, halving the height lowers the speed by a factor of √2.',src:'aamc-phys-qpack:Q111'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'An object slides from rest down a frictionless track, dropping 20 m vertically. What is its speed at the bottom? (g = 10 m/s²)',choices:['14 m/s','20 m/s','40 m/s','200 m/s'],ans:1,exp:'**v = √(2gh)** = √(2 × 10 × 20) = √400 = 20 m/s, regardless of the mass or the track\'s shape. Only the vertical drop matters when there is no friction.',src:'aamc-phys-qpack:Q111b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Adjacent nodes of a standing wave on a string are 0.25 m apart. What is the wavelength?',choices:['0.25 m','1.0 m','0.50 m','0.125 m'],ans:2,exp:'Adjacent nodes are **half a wavelength** apart, so λ = 2 × 0.25 = 0.50 m. Antinodes sit midway between nodes, also λ/2 apart from each other.',src:'aamc-phys-qpack:Q112'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'In a standing wave, what is the distance between a node and the nearest antinode?',choices:['λ/2','λ','2λ','λ/4'],ans:3,exp:'Nodes are λ/2 apart and each antinode sits halfway between them, so a node and its neighboring antinode are **λ/4** apart. This λ/4 spacing is why a pipe closed at one end has a fundamental of λ = 4L.',src:'aamc-phys-qpack:Q112b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A standing wave forms from the superposition of:',choices:['two identical waves moving in opposite directions','two identical waves moving in the same direction','two waves with slightly different frequencies','one wave passing into a denser medium'],ans:0,exp:'A **standing wave** results from two waves of equal amplitude and frequency traveling in **opposite directions**, usually an incident wave and its reflection. Two waves of slightly different frequency produce beats instead.',src:'aamc-phys-qpack:Q113'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'A pipe 0.50 m long is closed at one end. What is its fundamental frequency? (speed of sound = 340 m/s)',choices:['340 Hz','170 Hz','680 Hz','85 Hz'],ans:1,exp:'A pipe closed at one end has a node at the closed end and an antinode at the open end, so **λ = 4L** = 2.0 m and f = v/λ = 340/2.0 = 170 Hz. Using λ = 2L (open pipe) gives 340 Hz.',src:'aamc-phys-qpack:Q113b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'A laser cavity 0.30 m long supports a standing light wave of wavelength 600 nm. Using m = 2L/λ, what is the mode number m?',choices:['5.0 × 10⁵','2.0 × 10⁶','1.0 × 10⁶','1.0 × 10³'],ans:2,exp:'A standing wave fits an integer number of **half-wavelengths** in the cavity: m = 2L/λ = 0.60 m / (6.0 × 10⁻⁷ m) = 1.0 × 10⁶. Forgetting the factor of 2 gives 5.0 × 10⁵.',src:'aamc-phys-qpack:Q114'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'For a cavity of length 0.15 m with nodes at both ends, the frequency spacing between adjacent standing-wave modes is c/2L. What is it?',choices:['2.0 × 10⁹ Hz','5.0 × 10⁸ Hz','4.5 × 10⁷ Hz','1.0 × 10⁹ Hz'],ans:3,exp:'Allowed modes satisfy **fₘ = mc/2L**, so adjacent modes differ by c/2L = (3.0 × 10⁸)/(0.30) = 1.0 × 10⁹ Hz. This mirrors a string fixed at both ends, whose harmonics are spaced by the fundamental v/2L.',src:'aamc-phys-qpack:Q114b'},
  {s:'Waves & Sound',disc:'physics',aamc:'4D',q:'Tuning forks of 256 Hz and 260 Hz are struck together. What beat frequency is heard?',choices:['4 Hz','258 Hz','516 Hz','2 Hz'],ans:0,exp:'The **beat frequency** equals the difference of the two frequencies, |f₁ − f₂| = 4 Hz. The 258 Hz average is the pitch actually heard, pulsing in loudness 4 times per second.',src:'aamc-phys-qpack:Q115'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Two light beams differ in frequency by 1.0 × 10⁹ Hz. What wavelength corresponds to their beat frequency?',choices:['3.0 m','0.30 m','0.030 m','3.3 m'],ans:1,exp:'The beat frequency is **Δf** = 1.0 × 10⁹ Hz, and the corresponding wavelength is λ = c/Δf = (3.0 × 10⁸)/(1.0 × 10⁹) = 0.30 m, a microwave-range wavelength. Inverting the ratio gives 3.3 m.',src:'aamc-phys-qpack:Q115b'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'Forces of 5 N and 12 N act on the same object in any directions. Which resultant magnitude is IMPOSSIBLE?',choices:['7 N','13 N','3 N','17 N'],ans:2,exp:'The resultant of two forces lies between **|F₁ − F₂|** and **F₁ + F₂**, here 7 N to 17 N, so 3 N cannot occur. 13 N is the result when the forces are perpendicular (√(25 + 144)).',src:'aamc-phys-qpack:Q116'},
  {s:'Kinematics, Forces & Energy',disc:'physics',aamc:'4A',q:'Perpendicular forces of 6 N and 8 N act on an object. What is the magnitude of the net force?',choices:['14 N','2 N','48 N','10 N'],ans:3,exp:'Perpendicular vectors add by the **Pythagorean theorem**: √(6² + 8²) = √100 = 10 N. Adding magnitudes directly (14 N) applies only when the forces point the same way.',src:'aamc-phys-qpack:Q116b'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'A copper wire\'s length is doubled and its diameter is also doubled. Its resistance becomes:',choices:['one-half as large','twice as large','one-quarter as large','the same as before'],ans:0,exp:'**R = ρL/A**: doubling L doubles R, while doubling the diameter quadruples the area and divides R by 4, for a net factor of 2/4 = 1/2. Remember that area scales with diameter squared.',src:'aamc-phys-qpack:Q117'},
  {s:'Electricity & Magnetism',disc:'physics',aamc:'4C',q:'The voltage across an ohmic resistor at constant temperature is doubled. What happens?',choices:['Resistance doubles; current unchanged','Resistance unchanged; current doubles','Resistance halves; current quadruples','Resistance doubles; current doubles'],ans:1,exp:'Resistance depends only on the material and geometry (**R = ρL/A**), not on the applied voltage, so by **Ohm\'s law**, I = V/R, the current doubles. The power, V²/R, quadruples.',src:'aamc-phys-qpack:Q117b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'An object sits 30 cm from a converging lens with a focal length of 10 cm. The image is:',choices:['virtual and upright','virtual and inverted','real and inverted','real and upright'],ans:2,exp:'With the object outside the focal point, 1/i = 1/10 − 1/30 gives **i = +15 cm**, a **real, inverted** image on the far side (m = −0.5). Only an object inside f gives a virtual, upright, magnified image.',src:'aamc-phys-qpack:Q118'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'An object is placed 10 cm from a converging lens with a focal length of 20 cm. What is the magnification?',choices:['−2','+0.5','−0.5','+2'],ans:3,exp:'1/i = 1/20 − 1/10 = −1/20, so **i = −20 cm** (virtual, same side as the object), and m = −i/o = −(−20)/10 = +2. The positive sign means upright; this is how a magnifying glass works.',src:'aamc-phys-qpack:Q118b'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Potassium-40 (Z = 19) undergoes electron capture. What is the product?',choices:['Argon-40 (Z = 18)','Calcium-40 (Z = 20)','Potassium-39 (Z = 19)','Chlorine-36 (Z = 17)'],ans:0,exp:'In **electron capture** an inner electron combines with a proton to form a neutron, so Z falls by 1 and A is unchanged: K-40 → Ar-40. Calcium-40 is the beta-minus product, which K-40 can also form.',src:'aamc-phys-qpack:Q119'},
  {s:'Atomic & Nuclear Physics',disc:'physics',aamc:'4E',q:'Which decay mode produces the same change in Z and A as electron capture?',choices:['Beta-minus emission','Positron emission','Alpha emission','Gamma emission'],ans:1,exp:'Both **positron emission** and **electron capture** convert a proton into a neutron, lowering Z by 1 with A unchanged. Beta-minus raises Z, alpha lowers A by 4, and gamma changes neither.',src:'aamc-phys-qpack:Q119b'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'Light in air strikes a water surface at 40° from the normal. Compared with 40°, the reflection and refraction angles are:',choices:['reflection 40°; refraction greater than 40°','reflection less than 40°; refraction 40°','reflection 40°; refraction less than 40°','reflection greater than 40°; refraction 40°'],ans:2,exp:'The **law of reflection** makes the reflection angle equal to the incidence angle (40°). Entering the higher-index water, light bends **toward the normal**, so the refraction angle is smaller (about 29° for n = 1.33).',src:'aamc-phys-qpack:Q120'},
  {s:'Light & Optics',disc:'physics',aamc:'4D',q:'What is the approximate critical angle for light traveling from glass (n = 1.5) into air?',choices:['48°','34°','56°','42°'],ans:3,exp:'**sin θc = n₂/n₁** = 1/1.5 ≈ 0.67, so θc ≈ 42°. Beyond this angle, light inside the glass is totally internally reflected, the principle behind optical fibers and endoscopes.',src:'aamc-phys-qpack:Q120b'},
];
